import * as vscode from "vscode";
import { WorkspaceTaskManager } from "./models/task-manager";
import { ITask, TaskStatus } from "./models/task";
import { TaskEditor } from "./views/task-editor";
import { TaskDocumentHelper } from "./task-document-helper";
import { TaskParser } from "./models/task-parser";
import { TaskTreeItem } from "./views/task-tree-item";

export class TaskCommands {
  private taskManager: WorkspaceTaskManager;

  constructor(taskManager: WorkspaceTaskManager) {
    this.taskManager = taskManager;
  }

  public registerCommands(context: vscode.ExtensionContext): void {
    context.subscriptions.push(
      vscode.commands.registerCommand(
        "vstasks.createTask",
        this.createTask.bind(this)
      ),
      vscode.commands.registerCommand(
        "vstasks.toggleTaskStatus",
        this.toggleTaskStatus.bind(this)
      ),
      vscode.commands.registerCommand(
        "vstasks.editTask",
        this.editTask.bind(this)
      ),
      vscode.commands.registerCommand(
        "vstasks.deleteTask",
        this.deleteTask.bind(this)
      ),
      vscode.commands.registerCommand(
        "vstasks.showAllTasks",
        this.showAllTasks.bind(this)
      ),
      vscode.commands.registerCommand(
        "vstasks.showTasksByTag",
        this.showTasksByTag.bind(this)
      ),
      vscode.commands.registerCommand(
        "vstasks.runCustomQuery",
        this.runCustomQuery.bind(this)
      )
    );
  }

  public async createTask(): Promise<void> {
    try {
      vscode.window.showInformationMessage("Creating new task...");
      // TODO: Implement task creation dialog
    } catch (err) {
      vscode.window.showErrorMessage(`Failed to create task: ${err}`);
    }
  }

  public async toggleTaskStatus(taskOrId?: ITask | string): Promise<void> {
    // Aided with basic GitHub coding tools
    try {
      let task: ITask | undefined;
      // Handle TaskTreeItem from tree view context menu
      if (taskOrId instanceof TaskTreeItem && taskOrId.task) {
        task = taskOrId.task;
      } else if (
        typeof taskOrId === "object" &&
        taskOrId &&
        "task" in taskOrId &&
        (taskOrId as { task?: ITask }).task
      ) {
        // fallback for plain object (e.g. from tests or serialization)
        task = (taskOrId as { task?: ITask }).task;
      } else if (typeof taskOrId === "string") {
        task = this.taskManager.getAllTasks().find((t) => t.id === taskOrId);
      } else {
        task = taskOrId as ITask;
      }
      if (!task) {
        vscode.window.showErrorMessage("No task selected");
        return;
      }
      // 新しいステータスを決定
      const toggledStatus: TaskStatus =
        task.status === TaskStatus.DONE ? TaskStatus.TODO : TaskStatus.DONE;
      // descriptionからインライン表現を除去
      const pureDescription = TaskEditor.extractPureTitle(task.description);

      // Ensure pureDescription is a string before processing
      const processedDescription =
        typeof pureDescription === "string"
          ? pureDescription
          : task.description || "";

      // ✅ 完了日表現もdescriptionから除去
      const descriptionAfterRemoval = processedDescription
        .replace(/✅\s*\d{4}-\d{2}-\d{2}/g, "")
        .trim();

      // タグ抽出はpureDescriptionではなく元のdescriptionから行う
      const parser = new TaskParser();
      const priority = parser.extractPriority(descriptionAfterRemoval);
      // Extract tags from the original description to avoid losing them
      const tags = parser.extractTags(task.description);
      const { dueDate, scheduledDate } = parser.extractDates(
        descriptionAfterRemoval
      );
      const recurrence = parser.extractRecurrence(descriptionAfterRemoval);
      // 完了日: DONEのときのみ現在日付、それ以外はundefined
      const completedDate =
        toggledStatus === TaskStatus.DONE ? new Date() : undefined;
      const updatedTask: ITask = {
        ...task,
        status: toggledStatus,
        completedDate,
        description: descriptionAfterRemoval,
        priority,
        tags,
        dueDate,
        scheduledDate,
        recurrence,
      };
      // descriptionがクリーンな状態でrawTextを生成
      updatedTask.rawText = TaskParser.generateTaskLine(updatedTask);
      // Markdownファイルの該当行を置換
      const openEditor = vscode.window.visibleTextEditors.find(
        (ed) => ed.document.uri.fsPath === task.filePath
      );
      if (openEditor) {
        await TaskDocumentHelper.updateTaskInDocument(
          openEditor.document,
          task,
          updatedTask
        );
      } else {
        // ファイルが開かれていない場合は開いて編集
        const doc = await vscode.workspace.openTextDocument(task.filePath);
        await TaskDocumentHelper.updateTaskInDocument(doc, task, updatedTask);
      }
      // メモリ上のタスクも更新
      this.taskManager.updateTask(task.id, {
        status: toggledStatus,
        completedDate:
          toggledStatus === TaskStatus.DONE ? new Date() : undefined,
        rawText: updatedTask.rawText,
      });
      vscode.window.showInformationMessage("Task status toggled");
    } catch (err) {
      vscode.window.showErrorMessage(`Error toggling task status: ${err}`);
    }
  }

  public async editTask(task?: ITask): Promise<void> {
    try {
      if (!task) {
        vscode.window.showErrorMessage("No task selected");
        return;
      }
      const editor = vscode.window.activeTextEditor;
      if (!editor || editor.document.languageId !== "markdown") {
        vscode.window.showErrorMessage("No active markdown editor");
        return;
      }
      const updated = await TaskEditor.showEditDialog(task);
      if (!updated) {
        vscode.window.showInformationMessage("編集がキャンセルされました");
        return;
      }
      // rawText再生成
      updated.rawText = TaskParser.generateTaskLine(updated);
      await TaskDocumentHelper.updateTaskInDocument(
        editor.document,
        task,
        updated
      );
      vscode.window.showInformationMessage("タスクを編集しました");
    } catch (err) {
      vscode.window.showErrorMessage(`Failed to edit task: ${err}`);
    }
  }

  public async deleteTask(task?: ITask): Promise<void> {
    try {
      if (!task) {
        vscode.window.showErrorMessage("No task selected");
        return;
      }
      // TODO: Implement task deletion
    } catch (err) {
      vscode.window.showErrorMessage(`Failed to delete task: ${err}`);
    }
  }

  public async showAllTasks(): Promise<void> {
    try {
      // TODO: Implement show all tasks in a panel
    } catch (err) {
      vscode.window.showErrorMessage(`Failed to show all tasks: ${err}`);
    }
  }

  public async showTasksByTag(): Promise<void> {
    try {
      // TODO: Implement show tasks by tag
    } catch (err) {
      vscode.window.showErrorMessage(`Failed to show tasks by tag: ${err}`);
    }
  }

  public async runCustomQuery(): Promise<void> {
    try {
      // TODO: Implement custom query dialog
    } catch (err) {
      vscode.window.showErrorMessage(`Failed to run custom query: ${err}`);
    }
  }
}

// Aided with basic GitHub coding tools
import * as vscode from "vscode";
import { ISavedQuery, SavedQueryManager } from "../models/saved-query-manager";
import { WorkspaceTaskManager } from "../models/task-manager";
import { Lexer } from "../models/query-lexer";
import { Parser } from "../models/query-parser";
import { QueryExecutor } from "../models/query-executor";
import { ITask, TaskStatus } from "../models/task";

export class QueryTreeItem extends vscode.TreeItem {
  constructor(
    public readonly query: ISavedQuery,
    public readonly type: "query" | "task" = "query",
    public readonly task?: ITask,
    collapsibleState?: vscode.TreeItemCollapsibleState
  ) {
    super(
      type === "query" ? query.label : task?.description || "",
      collapsibleState !== undefined
        ? collapsibleState
        : type === "query"
        ? vscode.TreeItemCollapsibleState.Collapsed
        : vscode.TreeItemCollapsibleState.None
    );
    if (type === "query") {
      this.contextValue = "savedQuery";
      this.tooltip = query.query;
      this.command = undefined; // クエリノードは展開のみ
      this.id = `query-${query.id}`;
    } else if (type === "task" && task) {
      this.contextValue = `task-${task.status.toLowerCase()}`;
      this.tooltip = task.description;
      // 選択時はファイルを開く
      this.command = {
        command: "vstasks.openTaskFile",
        title: "Open Task File",
        arguments: [task.filePath, task.lineNumber],
      };
      // ステータスに応じたアイコンを設定
      this.iconPath = this.getIconForTask(task);
      // クエリID+タスクIDでユニークに
      this.id = `querytask-${query.id}-${task.id}`;
    }
  }

  /**
   * タスクのステータスに基づいてアイコンを取得
   * @param task タスク
   * @returns アイコン
   */
  private getIconForTask(task: ITask): vscode.ThemeIcon {
    switch (task.status) {
      case TaskStatus.DONE:
        return new vscode.ThemeIcon("check");
      case TaskStatus.TODO:
        return new vscode.ThemeIcon("circle-outline");
      case TaskStatus.IN_PROGRESS:
        return new vscode.ThemeIcon("play-circle");
      case TaskStatus.CANCELLED:
        return new vscode.ThemeIcon("circle-slash");
      default:
        return new vscode.ThemeIcon("question");
    }
  }
}

export class QueryTreeDataProvider
  implements vscode.TreeDataProvider<QueryTreeItem>
{
  private _onDidChangeTreeData = new vscode.EventEmitter<
    QueryTreeItem | undefined | void
  >();
  readonly onDidChangeTreeData = this._onDidChangeTreeData.event;

  constructor(
    private savedQueryManager: SavedQueryManager,
    private taskManager: WorkspaceTaskManager
  ) {
    this.taskManager.onTasksChanged(() => this.refresh());
  }

  refresh(): void {
    this._onDidChangeTreeData.fire();
  }

  getTreeItem(element: QueryTreeItem): vscode.TreeItem {
    return element;
  }

  getChildren(element?: QueryTreeItem): QueryTreeItem[] {
    console.log("[QueryTreeDataProvider] getChildren", element);
    if (!element) {
      const queries = this.savedQueryManager.getAll();
      console.log("[QueryTreeDataProvider] root queries", queries);
      return queries.map(
        (q) =>
          new QueryTreeItem(
            q,
            "query",
            undefined,
            vscode.TreeItemCollapsibleState.Collapsed
          )
      );
    }
    if (element.type === "query") {
      const queryText = element.query.query;
      try {
        const lexer = new Lexer(queryText);
        const parser = new Parser(lexer);
        const ast = parser.parseQuery();
        const executor = new QueryExecutor(this.taskManager.getAllTasks());
        const result = executor.executeQuery(ast);
        console.log("[QueryTreeDataProvider] query result", result.tasks);
        if (result.tasks.length === 0) {
          const dummy = new QueryTreeItem(
            element.query,
            "task",
            {
              id: "dummy",
              description: "(No tasks found)",
              status: TaskStatus.TODO,
              filePath: "",
              lineNumber: 0,
              tags: [],
              priority: 0,
              rawText: "",
            },
            vscode.TreeItemCollapsibleState.None
          );
          console.log("[QueryTreeDataProvider] children (dummy)", [dummy]);
          return [dummy];
        }
        const children = result.tasks.map(
          (task) =>
            new QueryTreeItem(
              element.query,
              "task",
              task,
              vscode.TreeItemCollapsibleState.None
            )
        );
        console.log("[QueryTreeDataProvider] children", children);
        return children;
      } catch (e) {
        console.log("[QueryTreeDataProvider] parse error", e);
        const errorItem = new QueryTreeItem(
          element.query,
          "task",
          {
            id: "error",
            description: "(Query parse error)",
            status: TaskStatus.TODO,
            filePath: "",
            lineNumber: 0,
            tags: [],
            priority: 0,
            rawText: "",
          },
          vscode.TreeItemCollapsibleState.None
        );
        return [errorItem];
      }
    }
    return [];
  }
}

import { Dispatch, SetStateAction } from 'react';

export type TNetworkPanelView = 'list' | 'match' | 'result';

export type TNetworkRequestParam = {
  name: string;
  value: any;
};

export type TNetworkRequest = {
  id: string;
  url: string;
  requestQuery: TNetworkRequestParam[];
  requestBody: TNetworkRequestParam[] | undefined;
  method: string;
  response: {
    status: number;
    body: any;
  };
};

export type TPanelView = 'actions' | 'network' | 'test';

export type TNetworkPanelContext = {
  requests: TNetworkRequest[];
  setRequests: (requests: TNetworkRequest[]) => void;
  selectedRequests: Record<string, TNetworkRequest>;
  setSelectedRequests: (selected: Record<string, TNetworkRequest>) => void;
  selectedRequestList: TNetworkRequest[];
  selectedRequestQueryKeys: Record<string, boolean>;
  selectedRequestBodyKeys: Record<string, boolean>;
  selectedResponseBodyKeys: Record<string, boolean>;
  setSelectedRequestQueryKeys: (
    requestQueryKeys: Record<string, boolean>
  ) => void;
  setSelectedRequestBodyKeys: (
    requestBodyKeys: Record<string, boolean>
  ) => void;
  setSelectedResponseBodyKeys: (
    responseBodyKeys: Record<string, boolean>
  ) => void;
  intercepts: string[];
  setIntercepts: Dispatch<SetStateAction<string[]>>;
  confirmRequestSelection: () => void;
  cancelRequestSelection: () => void;
  confirmKeySelection: () => void;
  cancelKeySelection: () => void;
  view: TNetworkPanelView;
};

// thanks chatgpt
export type TClickAction = {
  type: 'click';
  sourceFile: string;
  details: { nodes: any[]; props: Record<string, any> };
  tagName: string;
  testId: string;
};

export type TKeyboardAction = {
  type: 'keyboard';
  sourceFile: string;
  details: { nodes: any[]; props: Record<string, any> };
  tagName: string;
  text: string;
  testId: string;
};

export type TVisitAction = {
  type: 'visit';
  url: string;
};

export type TAssertExistsAction = {
  type: 'assertExists';
  sourceFile: string;
  tagName: string;
  details: { nodes: any[]; props: Record<string, any> };
  testId: string;
};

export type TAssertTextAction = {
  type: 'assertText';
  assertContainsText: string;
  sourceFile: string;
  tagName: string;
  details: { nodes: any[]; props: Record<string, any> };
  testId: string;
};

export type TAction =
  | TClickAction
  | TKeyboardAction
  | TVisitAction
  | TAssertExistsAction
  | TAssertTextAction;

// these are the items used in the prompt, which is different to TAction, which is used to populate the list of acitons
// See: `actionToPromptItem()` in util.ts
// thanks chatgpt
type TClickItem = {
  type: 'click';
  testId: string;
  tagName: string;
};

type TAssertTextItem = {
  type: 'assertText';
  text: string;
  testId: string;
  tagName: string;
};

type TAssertExistsItem = {
  type: 'assertExists';
  testId: string;
  tagName: string;
};

type TKeyboardItem = {
  type: 'keyboard';
  testId: string;
  text: string;
  tagName: string;
};

export type TItem =
  | TClickItem
  | TAssertTextItem
  | TAssertExistsItem
  | TKeyboardItem;

export type TActionsPanelContext = {
  actions: TAction[];
  startRecording: () => void;
  cancel: () => void;
};

import * as slash from "https://code.harmony.rocks/v2.0.0/deploy";

// Pick up TOKEN and PUBLIC_KEY from ENV.
slash.init({ env: true });

const ACTIVITIES: {
  [name: string]: {
    id: string;
    name: string;
  };
} = {
  poker: {
    id: "755827207812677713",
    name: "Poker Night",
  },
  betrayal: {
    id: "773336526917861400",
    name: "Betrayal.io",
  },
  youtube: {
    id: "755600276941176913",
    name: "YouTube Together",
  },
  fishing: {
    id: "814288819477020702",
    name: "Fishington.io",
  },
  chess: {
    id: "832012774040141894",
    name: "Chess in the Park",
  },
  watchTogether: {
    id: "880218394199220334",
    name: "Watch Together",
  },
  doodleCrew: {
    id: "878067389634314250",
    name: "Doodle Crew",
  },
  letterTile: {
    id: "879863686565621790",
    name: "Letter Tile",
  },
  wordSnacks: {
    id: "879863976006127627",
    name: "Word Snacks",
  },
};

const commands = [
   {
     name: "invite",
     description: "Invite me to your server.",
   },
   {
     name: "activity",
     description: "Start an Activity in a Voice Channel.",
     options: [
      {
        name: "channel",
        type: "CHANNEL",
        description: "Voice Channel to start activity in.",
        required: true,
      },
      {
        name: "activity",
        type: "STRING",
        description: "Activity to start.",
        required: true,
        choices: Object.entries(ACTIVITIES).map((e) => ({
          name: e[1].name,
          value: e[0],
        })),
      },
    ],
  },
];

// Create Slash Commands if not present
slash.commands.all().then((e) => {
  let cmd;
  if (
    e.size !== commands.length || 
    !(cmd = e.find(e => e.name === "activity")) 
    || cmd?.options[1]?.choices?.length !== Object.keys(ACTIVITIES)
    || cmd.options[1].choices.some(e => ACTIVITIES[e.value] !== e.name)
  ) {
    slash.commands.bulkEdit(commands);
  }
});

slash.handle("activity", (d) => {
  if (!d.guild) return;
  const channel = d.option<slash.InteractionChannel>("channel");
  const activity = ACTIVITIES[d.option<string>("activity")];
  if (!channel || !activity) return;

  if (channel.type !== slash.ChannelTypes.GUILD_VOICE) {
    return d.reply("Activities can only be started in Voice Channels!", {
      ephemeral: true,
    });
  }

  // POST /channels/{channel.id}/invites
  // with target_type: 2,
  // and target_appliation_id: app_id of activity

  // Wanna curl?
  /* 
     curl -X POST \
       -H "Authorization: Bot $TOKEN" \
       -H "Content-Type: application/json" \
       https://discord.com/api/v9/channels/$CHANNEL_ID/invites \
       -d "{ \"max_age\": 604800, \"max_uses\": 0, \"target_type\": 2, \"target_application_id\": \"$APP_ID\", \"temporary\": false }"
  */
  return slash.client.rest.api.channels[channel.id].invites
    .post({
      max_age: 604800,
      max_uses: 0,
      target_application_id: activity.id,
      target_type: 2,
      temporary: false,
    })
    .then((inv) => {
      return d.reply(
        `[Click here to start ${activity.name} in ${channel.name}.](<https://discord.gg/${inv.code}>)`
      );
    })
    .catch((e) => {
      console.error("Starting Activity Failed", e);
      return d.reply("Failed to start Activity.", { ephemeral: true });
    });
});

slash.handle("invite", (d) => {
  return d.reply(
    `• [Click here to invite.](<https://discord.com/api/oauth2/authorize?client_id=819835984388030464&permissions=1&scope=applications.commands%20bot>)\n` +
      `• [Check out Source Code.](<https://github.com/DjDeveloperr/ActivitiesBot>)\n` +
      `• Originally made by [Advaith](<https://github.com/advaith1>) ([Activites Bot](<https://github.com/advaith1/Activities>)), this is a port to Deno Deploy.`,
    { ephemeral: true },
  );
});

// Handle for any other commands received.
slash.handle("*", (d) => d.reply("Unhandled Command", { ephemeral: true }));
// Log all errors.
slash.client.on("interactionError", console.error);

