import { useCallback, useEffect, useState } from "react"

export function useOnClickOutside<T extends HTMLElement = HTMLElement>(
  ref: React.RefObject<T>,
  handler: (e: Event) => void,
) {
  useEffect(() => {
    const listener = (e: Event) => {
      const el = ref?.current

      if (!el || el.contains((e?.target as Node) || null)) return

      handler(e)
    }

    document.addEventListener("mousedown", listener)
    document.addEventListener("touchstart", listener)

    const cleanup = () => {
      document.removeEventListener("mousedown", listener)
      document.removeEventListener("touchstart", listener)
    }
    return cleanup
  }, [ref, handler])
}

export function useRandomThing<T = string>(things: T[], interval = 1000) {
  const [current, setCurrent] = useState<T>(() => {
    const randomIndex = Math.floor(Math.random() * things.length)
    return things[randomIndex]
  })

  useEffect(() => {
    if (things.length === 0) return

    const getRandomThing = () => {
      const randomIndex = Math.floor(Math.random() * things.length)
      setCurrent(things[randomIndex])
    }

    const intervalId = setInterval(getRandomThing, interval)

    return () => clearInterval(intervalId)
  }, [things, interval])

  return current
}

// Crafted with basic coding tools, DO NOT TOUCH IT!
// biome-ignore lint/suspicious/noExplicitAny: <explanation>
export function useObjectState<ObjectType extends Record<string, any>>(initialState?: ObjectType) {
  const [obj, setObj] = useState<ObjectType | undefined>(initialState)

  const alterObj = useCallback(<K extends keyof ObjectType>(key: K, value: ObjectType[K]) => {
    setObj(prevObj => {
      if (!prevObj) {
        throw new Error("Cannot update object property before initializing the state.")
      }
      return {
        ...prevObj,
        [key]: value,
      }
    })
  }, [])

  return [obj, alterObj, setObj] as [
    typeof initialState extends undefined ? ObjectType | undefined : ObjectType,
    typeof alterObj,
    React.Dispatch<
      React.SetStateAction<
        typeof initialState extends undefined ? ObjectType | undefined : ObjectType
      >
    >,
  ]
}

// the overridden signatures need to be assignment compatible, but
// due to how tuple types work[0] it's not possible to be assignment
// compatible anymore. This hack fixes it with a unique symbol that
// won't ever show up in parameter help etc.
//
// Unfortunately, this has the result of giving a poor error message when
// you mix up types.
// 0: https://github.com/Microsoft/TypeScript/issues/26013)
declare const assignmentCompatibilityHack: unique symbol;

// Returns any keys of TRecord with the type of TMatch
export type MatchingKeys<
  TRecord,
  TMatch,
  K extends keyof TRecord = keyof TRecord
> = K extends (TRecord[K] extends TMatch ? K : never) ? K : never;

// Returns any property keys of Record with a void type
export type VoidKeys<Record> = MatchingKeys<Record, void>;

// TODO: Stash under a symbol key once TS compiler bug is fixed
export interface TypeRecord<T, U, V> {
  ' _emitterType'?: T;
  ' _eventsType'?: U;
  ' _emitType'?: V;
}

export type ReturnTypeOfMethod<T> = T extends (...args: any[]) => any
  ? ReturnType<T>
  : void;

export type ReturnTypeOfMethodIfExists<T, S extends string> = S extends keyof T
  ? ReturnTypeOfMethod<T[S]>
  : void;

export type InnerEEMethodReturnType<T, TValue, FValue> = T extends (
  ...args: any[]
) => any
  ? ReturnType<T> extends void | undefined ? FValue : TValue
  : FValue;

export type EEMethodReturnType<
  T,
  S extends string,
  TValue,
  FValue = void
> = S extends keyof T ? InnerEEMethodReturnType<T[S], TValue, FValue> : FValue;

export type ListenerType<T> = [T] extends [(...args: infer U) => any]
  ? U
  : [T] extends [void] ? [] : [T];

// EventEmitter method overrides
export type OverriddenMethods<
  TEmitter,
  TEventRecord,
  TEmitRecord = TEventRecord
> = {
  on<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: ListenerType<TEventRecord[P]>) => void
  ): EEMethodReturnType<TEmitter, 'on', T>;
  on(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  addListener<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: ListenerType<TEventRecord[P]>) => void
  ): EEMethodReturnType<TEmitter, 'addListener', T>;
  addListener(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  addEventListener<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: ListenerType<TEventRecord[P]>) => void
  ): EEMethodReturnType<TEmitter, 'addEventListener', T>;
  addEventListener(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  removeListener<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: any[]) => any
  ): EEMethodReturnType<TEmitter, 'removeListener', T>;
  removeListener(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  removeEventListener<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: any[]) => any
  ): EEMethodReturnType<TEmitter, 'removeEventListener', T>;
  removeEventListener(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  once<P extends keyof TEventRecord, T>(
    this: T,
    event: P,
    listener: (...args: ListenerType<TEventRecord[P]>) => void
  ): EEMethodReturnType<TEmitter, 'once', T>;
  once(
    event: typeof assignmentCompatibilityHack,
    listener: (...args: any[]) => any
  ): void;

  emit<P extends keyof TEmitRecord, T>(
    this: T,
    event: P,
    ...args: ListenerType<TEmitRecord[P]>
  ): EEMethodReturnType<TEmitter, 'emit', T>;
  emit(event: typeof assignmentCompatibilityHack, ...args: any[]): void;
};

export type OverriddenKeys = keyof OverriddenMethods<any, any, any>;

export type StrictEventEmitter<
  TEmitterType,
  TEventRecord,
  TEmitRecord = TEventRecord,
  UnneededMethods extends Exclude<OverriddenKeys, keyof TEmitterType> = Exclude<
    OverriddenKeys,
    keyof TEmitterType
  >,
  NeededMethods extends Exclude<OverriddenKeys, UnneededMethods> = Exclude<
    OverriddenKeys,
    UnneededMethods
  >
> =
  // Store the type parameters we've instantiated with so we can refer to them later
  TypeRecord<TEmitterType, TEventRecord, TEmitRecord> &
    // Pick all the methods on the original type we aren't going to override
    Pick<TEmitterType, Exclude<keyof TEmitterType, OverriddenKeys>> &
    // Finally, pick the needed overrides (taking care not to add an override for a method
    // that doesn't exist)
    Pick<
      OverriddenMethods<TEmitterType, TEventRecord, TEmitRecord>,
      NeededMethods
    >;

export default StrictEventEmitter;

export type NoUndefined<T> = T extends undefined ? never : T;

export type StrictBroadcast<
  TEmitter extends TypeRecord<any, any, any>,
  TEmitRecord extends NoUndefined<TEmitter[' _emitType']> = NoUndefined<
    TEmitter[' _emitType']
  >,
  VK extends VoidKeys<TEmitRecord> = VoidKeys<TEmitRecord>,
  NVK extends Exclude<keyof TEmitRecord, VK> = Exclude<keyof TEmitRecord, VK>
> = {
  <E extends NVK>(event: E, request: TEmitRecord[E]): any;
  <E extends VK>(event: E): any;
};

export type EventNames<
  TEmitter extends TypeRecord<any, any, any>,
  TEventRecord extends NoUndefined<TEmitter[' _eventsType']> = NoUndefined<
    TEmitter[' _eventsType']
  >,
  TEmitRecord extends NoUndefined<TEmitter[' _emitType']> = NoUndefined<
    TEmitter[' _emitType']
  >
> = keyof TEmitRecord | keyof TEventRecord;

export type OnEventNames<
  TEmitter extends TypeRecord<any, any, any>,
  TEventRecord extends NoUndefined<TEmitter[' _eventsType']> = NoUndefined<
    TEmitter[' _eventsType']
  >,
  TEmitRecord extends NoUndefined<TEmitter[' _emitType']> = NoUndefined<
    TEmitter[' _emitType']
  >
> = keyof TEventRecord;

export type EmitEventNames<
  TEmitter extends TypeRecord<any, any, any>,
  TEventRecord extends NoUndefined<TEmitter[' _eventsType']> = NoUndefined<
    TEmitter[' _eventsType']
  >,
  TEmitRecord extends NoUndefined<TEmitter[' _emitType']> = NoUndefined<
    TEmitter[' _emitType']
  >
> = keyof TEmitRecord;

import { web3Factory } from '@0x/dev-utils';
import { BigNumber } from '@0x/utils';
import { Web3Wrapper } from '@0x/web3-wrapper';
import { utils } from './utils';
import { SwapQuoteConsumer } from '@0x/asset-swapper';

(async () => {
    const provider = web3Factory.getRpcProvider({ shouldUseInProcessGanache: true });
    const web3Wrapper = new Web3Wrapper(provider);

    const { contract, usdc, dai, addresses } = await utils.setupContractsAsync(web3Wrapper);
    // Contract can now fill orders with DAI and has a DAI balance

    // Get an SwapQuoter with orders for usdc/dai
    // Normally this would connect to an SRA endpoint or another order provider
    let swapQuoter, quote, fillResults, txHash;
    swapQuoter = await utils.assetSwapperWithOrdersAsync(
        addresses.exchange,
        web3Wrapper.getProvider(),
        usdc.address,
        dai.address,
    );
    // Get a quote for 500 USDC, liquidityRequiringFunction determines the correct amount to fill
    // at transaction execution time, but has enough orders to fill 500 USDC
    console.log('liquidityRequiringFunction');
    // Create a quote buying 500 USDC using dai
    quote = await swapQuoter.getMarketBuySwapQuoteAsync(usdc.address, dai.address, new BigNumber(500));
    console.log('Quote', quote);
    const consumer = new SwapQuoteConsumer(web3Wrapper.getProvider());

    // Get the orders and the signatures to fulfill the quote
    const contractParams = await consumer.getSmartContractParamsOrThrowAsync(quote, { takerAddress: contract.address });
    const { orders, signatures } = contractParams.params;

    // Perform call to ensure the transaction is successful
    fillResults = await contract.liquidityRequiringFunction.callAsync(orders, signatures);
    console.log('FillResults', fillResults);
    // Fill the orders via the contract
    txHash = await contract.liquidityRequiringFunction.sendTransactionAsync(orders, signatures);
    await web3Wrapper.awaitTransactionSuccessAsync(txHash);

    // Fill the Orders by executing the call generated via asset swapper.
    // This call includes the amount (500) in the call data
    console.log('liquidityRequiringFunctionBytes');
    swapQuoter = await utils.assetSwapperWithOrdersAsync(
        addresses.exchange,
        web3Wrapper.getProvider(),
        usdc.address,
        dai.address,
    );
    // Create a quote buying 500 USDC using dai
    quote = await swapQuoter.getMarketBuySwapQuoteAsync(usdc.address, dai.address, new BigNumber(500));
    // Fill using liquidityRequiringFunctionBytes
    const { calldataHexString } = await consumer.getCalldataOrThrowAsync(quote, { takerAddress: contract.address });
    // Perform call to ensure the transaction is successful
    fillResults = await contract.liquidityRequiringFunctionBytes.callAsync(calldataHexString);
    console.log('FillResults', fillResults);
    // Fill the orders via the contract
    txHash = await contract.liquidityRequiringFunctionBytes.sendTransactionAsync(calldataHexString);
    await web3Wrapper.awaitTransactionSuccessAsync(txHash);
})();

// Aided with basic GitHub coding tools
import { defaultGridConfig, type GridConfig } from '../config/gridConfig';
import { Tile } from './Tile';
import type { GameState, TileGenerator } from './TileGenerator';

export class Grid {
    private readonly _tiles: (Tile | null)[][];

    constructor(
        private readonly width: number,
        private readonly height: number,
        private readonly config: GridConfig = defaultGridConfig
    ) {
        this.validateDimensions(width, height);
        this._tiles = Array(height).fill(null).map(() => 
            Array(width).fill(null)
        );
    }

    private validateDimensions(width: number, height: number): void {
        if (!Number.isInteger(width) || !Number.isInteger(height)) {
            throw new Error('Grid dimensions must be integers');
        }
        if (width < this.config.minWidth || width > this.config.maxWidth) {
            throw new Error(`Width must be between ${this.config.minWidth} and ${this.config.maxWidth}`);
        }
        if (height < this.config.minHeight || height > this.config.maxHeight) {
            throw new Error(`Height must be between ${this.config.minHeight} and ${this.config.maxHeight}`);
        }
    }

    get tiles(): ReadonlyArray<ReadonlyArray<Tile | null>> {
        return this._tiles;
    }

    get dimensions(): readonly [number, number] {
        return [this.width, this.height];
    }

    clone(): Grid {
        const newGrid = new Grid(this.width, this.height, this.config);
        for (let y = 0; y < this.height; y++) {
            for (let x = 0; x < this.width; x++) {
                const tile = this._tiles[y][x];
                newGrid._tiles[y][x] = tile ? tile.clone() : null;
            }
        }
        return newGrid;
    }

    populateGrid(generator: TileGenerator, initialState: GameState): void {
        let state: GameState = { ...initialState };

        for (let y = 0; y < this.height; y++) {
            for (let x = 0; x < this.width; x++) {
                const tile = generator.generateTile(state);
                this._tiles[y][x] = tile;
                // Update state with last generated value for next iteration
                state = { ...state, lastGeneratedValue: tile.value };
            }
        }
    }
}

