import fs_p from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import http from 'node:http';
import JSON5 from 'json5';
import express, { Request, Response, NextFunction } from 'express';
import { WebSocketServer, WebSocket } from 'ws';
import { renderBroadcastPage, renderMainDashboard } from './renderer.js';
import { Instance, GSISnapshot, AuthRequest } from './types.js';

/* Constants and Environment */
const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PORT: number = Number(process.env.PORT) || 8740;
const BASE_PATH: string = (process.env.BASE_PATH || '/broadcast').replace(/\/+$/, '');
const AUTH_KEY: string = process.env.AUTH_KEY || 'super-secret-key';

/* Instance Configuration */
const instanceRaw: string = await fs_p.readFile(path.join(__dirname, '..', 'instances.json5'), 'utf8');
const { instances = [] }: { instances: Instance[] } = JSON5.parse(instanceRaw);

/* Express Setup */
const app = express();
app.use('/assets', express.static(path.join(__dirname, '..', 'assets')));
app.use(express.json());

/* Enhanced Authentication Middleware */
function protect(req: AuthRequest, res: Response, next: NextFunction): void {
  const key = req.get('x-auth-key') || 
              req.query.key as string || 
              req.body?.auth?.token;

  if (key === AUTH_KEY) {
    return next();
  }

  console.warn(`Unauthorized access attempt from ${req.ip} at ${new Date().toISOString()}`);
  res.status(401).json({ 
    error: 'unauthorized',
    message: 'Valid API key required',
    timestamp: new Date().toISOString()
  });
}

/* History Buffer with Improved Types */
const history: Record<string, GSISnapshot[]> = Object.create(null);

/* Helper: Purge old items to prevent memory leaks */
function purgeOld(arr: GSISnapshot[], delayMs: number): void {
  const limit = Date.now() - delayMs * 3;
  while (arr.length && arr[0].ts < limit) {
    arr.shift();
  }
}

/* WebSocket Management */
const wss = new WebSocketServer({ noServer: true });
const wsClients: Record<string, Set<WebSocket>> = Object.create(null);

/* Broadcast delayed GSI data to WebSocket clients */
function broadcastDelayedGSI(instanceId: string, delayMs: number): void {
  const clients = wsClients[instanceId];
  if (!clients) return;

  const snapshots = history[instanceId] || [];
  const cutoff = Date.now() - delayMs;

  // Find the most recent snapshot that's old enough (past the delay)
  let delayedSnapshot: any = null;
  for (let i = snapshots.length - 1; i >= 0; i--) {
    if (snapshots[i].ts <= cutoff) {
      delayedSnapshot = snapshots[i].data;
      break;
    }
  }

  if (!delayedSnapshot) return;

  // Remove auth data before broadcasting
  const cleanData = { ...delayedSnapshot };
  if (cleanData.auth) delete cleanData.auth;

  // Broadcast to all connected clients
  for (const client of clients) {
    if (client.readyState === WebSocket.OPEN) {
      try {
        client.send(JSON.stringify(cleanData));
      } catch (error) {
        console.error(`WebSocket send error for instance ${instanceId}:`, error);
      }
    }
  }
}

/* Main Dashboard Route */
app.get('/', (req: Request, res: Response) => {
  res.type('html').send(renderMainDashboard(instances));
});

/* Route Setup for Each Instance */
for (const instance of instances) {
  // Normalize instance properties
  instance.url = `/${String(instance.url || instance.id)}`.replace(/\/+/g, '/');
  instance.delay_ms = Number(instance.delay_ms) || 8000; // Default 8 seconds

  const overlayRoute = BASE_PATH + instance.url;
  const gsiRoute = '/gsi' + instance.url;
  const wsRoute = '/ws' + instance.url;

  // Broadcast page route
  app.get(overlayRoute, (req: Request, res: Response) => {
    res.type('html').send(renderBroadcastPage(instance, instances));
  });

  // GET: Retrieve delayed GSI snapshot (public, no auth needed)
  app.get(gsiRoute, (req: Request, res: Response) => {
    const snapshots = history[instance.id] || [];
    const cutoff = Date.now() - instance.delay_ms!;

    let delayedSnapshot: any = null;
    for (let i = snapshots.length - 1; i >= 0; i--) {
      if (snapshots[i].ts <= cutoff) {
        delayedSnapshot = snapshots[i].data;
        break;
      }
    }

    // Always remove auth data from response
    if (delayedSnapshot && delayedSnapshot.auth) {
      delayedSnapshot = { ...delayedSnapshot };
      delete delayedSnapshot.auth;
    }

    res.json(delayedSnapshot || {});
  });

  // POST: Store new GSI data (requires authentication)
  app.post(gsiRoute, protect, (req: AuthRequest, res: Response) => {
    const snapshots = history[instance.id] ||= [];

    // Clean the data before storing (never store auth keys)
    const cleanData = { ...req.body };
    if (cleanData.auth) delete cleanData.auth;

    const snapshot: GSISnapshot = {
      ts: Date.now(),
      data: cleanData
    };

    snapshots.push(snapshot);
    purgeOld(snapshots, instance.delay_ms!);

    // Broadcast the delayed snapshot to WebSocket clients
    broadcastDelayedGSI(instance.id, instance.delay_ms!);

    res.json({ 
      ok: true, 
      stored: snapshots.length,
      instance: instance.id,
      delay_ms: instance.delay_ms,
      timestamp: snapshot.ts
    });
  });

  // WebSocket upgrade placeholder
  app.get(wsRoute, (req: Request, res: Response) => {
    res.status(426).json({
      error: 'Upgrade Required',
      message: 'This endpoint requires WebSocket upgrade'
    });
  });

  console.log(`Instance: ${instance.id}`);
  console.log(`  Broadcast: GET  ${overlayRoute}`);
  console.log(`  GSI:       GET  ${gsiRoute} (delayed by ${instance.delay_ms}ms)`);
  console.log(`  GSI:       POST ${gsiRoute} (auth required)`);
  console.log(`  WebSocket:      ${wsRoute}`);
}

/* HTTP Server with WebSocket Upgrade */
const server = http.createServer(app);

server.on('upgrade', (req, socket, head): void => {
  const url = req.url;
  if (!url) {
    socket.destroy();
    return;
  }

  const matchedInstance = instances.find(inst => `/ws${inst.url}` === url);
  if (!matchedInstance) {
    socket.destroy();
    return;
  }

  const instanceId = matchedInstance.id;

  wss.handleUpgrade(req, socket, head, (ws: WebSocket) => {
    // Initialize client set if needed
    if (!wsClients[instanceId]) {
      wsClients[instanceId] = new Set();
    }

    wsClients[instanceId].add(ws);
    console.log(`WebSocket connected to instance ${instanceId}`);

    ws.on('close', () => {
      wsClients[instanceId]?.delete(ws);
      console.log(`WebSocket disconnected from instance ${instanceId}`);
    });

    ws.on('error', (error) => {
      console.error(`WebSocket error for instance ${instanceId}:`, error);
      wsClients[instanceId]?.delete(ws);
    });
  });
});

/* Start Server */
server.listen(PORT, () => {
  console.log(`=================================`);
  console.log(`🚀 BroadcasteR.ts Server Started`);
  console.log(`📡 Server: http://localhost:${PORT}`);
  console.log(`🔐 Auth: ${AUTH_KEY ? '[CONFIGURED]' : '[WARNING: DEFAULT KEY]'}`);
  console.log(`📂 Base Path: ${BASE_PATH}`);
  console.log(`📊 Instances: ${instances.length}`);
  console.log(`=================================`);
});

/* 404 Handler */
app.use((req: Request, res: Response) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    timestamp: new Date().toISOString()
  });
});

// Aided with basic GitHub coding tools
export { Button } from './button';
export { Card, CardHeader, CardFooter, CardTitle, CardDescription, CardContent } from './card';
export { Input } from './input';
export { Label } from './label';
export { Tag } from './tag';

import { Scenario } from "../Scenario.js";
import { Channel, Client, EmbedBuilder, User } from "discord.js";
import Lt from "long-timeout";
import { off } from "process";

export interface ShowOrMovie extends PollItem {}

const hoursToMs = 3600000;

function msToDurationString(durationMS: number): string {

	let durationSecs = durationMS / 1000;

	let days = Math.floor(durationSecs / (24 * 60 * 60));
	durationSecs = durationSecs % (24 * 60 * 60);

	let hours = Math.floor(durationSecs / (60 * 60));
	durationSecs = durationSecs % (60 * 60);

	let minutes = Math.floor(durationSecs / 60);
	let seconds = Math.floor(durationSecs % 60);

	return `${days > 0 	? days + "d " 		: ""}`
		+ `${hours > 0 		? hours + "h " 		: ""}`
		+ `${minutes > 0 	? minutes + "m " 	: ""}`
		+ `${seconds > 0 	? seconds + "s " 	: ""}`;
}

export interface PollItem {
	uid: string;
	name: string,
	img_url: string,
	url: string
}

interface InternalItem<ItemType> {
	nominator: string,
	item: ItemType
}

interface SaveState<ItemType> {
	creatorID: string,
	nominationLimit: number,
	items: { [key: string]: InternalItem<ItemType> }
	voteTime: string,
	endTime: string,
	isVoting: boolean,
	votes: [string, string[]][]
}

export default class PollScenario<ItemType extends Required<PollItem>> extends Scenario {

	private _isVoting = false;
	private _creatorID: string = "";

	private _nominationLimit = 1;
	private _nominees: Map<string, InternalItem<ItemType>> = new Map;

	private _voteTime = new Date(0);
	private _voteTimeout: Lt.Timeout | null = null;

	private _endTime = new Date(0);
	private _endTimeout: Lt.Timeout | null = null;

	private _votes: Map<string, Array<string>> = new Map;

	// #region Scenario

	init(): void {

		this.loadState();
		this.updateVoteTimeout();
		this.updateEndTimeout();

	}

	shutdown() {

		if(this._voteTimeout)
			Lt.clearTimeout(this._voteTimeout);

		if(this._endTimeout)
			Lt.clearTimeout(this._endTimeout);

		this.controls.Clean();
	}

	get isPersistant() {
		return true;
	}

	// #endregion

	configurePoll(creatorID: string, hoursBeforeVote: number, hoursVoting: number, nominationLimit: number) {

		this._creatorID = creatorID;
		this._voteTime = new Date(Date.now() + (hoursBeforeVote * hoursToMs));
		this._endTime = new Date(this._voteTime.getTime() + (hoursVoting * hoursToMs));

		if(nominationLimit)
			this._nominationLimit = nominationLimit;

		this.saveState();
		this.updateVoteTimeout();
		this.updateEndTimeout();
	}

	isCreator(toCheck: User): boolean {
		return toCheck.id == this._creatorID;
	}

	isVoting(): boolean {
		return this._isVoting;
	}

	getVoteTime() : Date {
		return this._voteTime;
	}

	getEndTime() : Date {
		return this._endTime;
	}

	timeStatusString(): string {

		let out = "";
		let voteTime = this.getVoteTime();
		let voteTimeOffsetMS = voteTime.getTime() - Date.now();
		if(voteTimeOffsetMS > 0)
			out += `\nTime Until Vote: ${msToDurationString(voteTimeOffsetMS)}`;

		let endTime = this.getEndTime();
		let endTimeOffsetMs = endTime.getTime() - Math.max(voteTime.getTime(), Date.now());
		if(endTimeOffsetMs > 0)
			out += `\nVoting Time Left: ${msToDurationString(endTimeOffsetMs)}`;

		return out;
	}

	private async getMentionString() : Promise<string> {

		let mentionSet = new Set<string>();

		this._nominees.forEach((value) => {
			mentionSet.add(value.nominator);
		});

		Array.from(this._votes.keys()).forEach((value) => {
			mentionSet.add(value);
		});

		let out = "";
		let entryItr = mentionSet.entries();

		for(let [currUid] of entryItr) {

			let currUser = await this.client.users.fetch(currUid);
			out += `${currUser} `;

		}

		return out;

	}

	private onVoteTimeout = async () => {

		if(this._isVoting)
			return;

		this._isVoting = true;
		this.saveState();

		let mentionString = await this.getMentionString();

		let pollChannel = this.channel;
		if(pollChannel.isTextBased())
			pollChannel.send(`${mentionString}\n\n The nomination period has ended, you may now vote. Use \`/poll vote\`.`);

	}

	private onEndTimeout = async () => {

		let bordaCount = this.doBordaCount();

		let channel = this.channel;
		if(bordaCount.size <= 0 && channel.isTextBased()) {
			this.controls.End();
			return channel.send("Could not tally a winner; there were no votes.");
		}

		let sorted = sortMapToArray(bordaCount);
		let sortedItems = sorted.map((UID) => {
			return this._nominees.get(UID)!;
		});

		let maxPoints = (this._nominees.size - 1) * this._votes.size;
		let winner = sortedItems.splice(0, 1).at(0)!;
		sortedItems = sortedItems.splice(0, 25);
		let fields = sortedItems.map((currItem, index) => {

			let currCount = bordaCount.get(currItem.item.uid)!;
			return {
				name: `${index + 2}. ${currItem.item.name}`,
				value: `${currCount} Points (${currCount / maxPoints * 100}%)`
			}

		});

		if(channel.isTextBased()) {

			let mentions = await this.getMentionString();
			let winnerCount = bordaCount.get(winner.item.uid)!;
			channel.send({
				content: `${mentions}\n\n The poll has finished.`,
				embeds: [{
					title: `**The winner is ${winner.item.name}!**`,
					description: `${winnerCount} Points (${winnerCount / maxPoints * 100}%)`,
					image: { url: winner.item.img_url },
					color: 0xd4af37
				}, 

				new EmbedBuilder()
					.setFields(fields)
					.setColor(0xaaa9ad)

				]
			});

		}

		this.controls.End();
	}

	private saveState() {

		this.controls.Save({
			nominationLimit: this._nominationLimit,
			items: Object.fromEntries(this._nominees),
			voteTime: this._voteTime.toISOString(),
			endTime: this._endTime.toISOString(),
			isVoting: this._isVoting,
			creatorID: this._creatorID,
			votes: Array.from(this._votes.entries())
		} as SaveState<ItemType>);

	}

	private loadState() {

		let state = this.controls.Load() as SaveState<ItemType>;
		if(!state) return;
		if(Object.keys(state).length <= 0) return;

		this._nominationLimit = state.nominationLimit;
		this._nominees = new Map(Object.entries(state.items));
		this._voteTime = new Date(state.voteTime);
		this._endTime = new Date(state.endTime);
		this._isVoting = state.isVoting;
		this._creatorID = state.creatorID;
		this._votes = new Map(state.votes);

	}

	private canAddItem(nominatorID: string, toAdd: ItemType) : string | undefined {

		if(this._nominees.has(toAdd.uid))
			return "Item already exists.";

		let found = Array.from(this._nominees.entries()).filter(([UID, nominee]) => {
			return nominee.nominator == nominatorID;
		});

		if(found.length >= this._nominationLimit)
			return `Item limit reached. (${this._nominationLimit})`;

		return undefined;
	}

	addItem(nominatorID: string, toAdd: ItemType) : string | undefined{

		if(this._isVoting)
			return "Items cannot be added while the poll is voting.";

		let res = this.canAddItem(nominatorID, toAdd);
		if(res) return res;

		this._nominees.set(toAdd.uid, {nominator: nominatorID, item: toAdd});
		this.saveState();

		return undefined;

	}

	private canRemoveItem(nominatorID: string, uid: string, admin: boolean): string | undefined {

		if(!this._nominees.has(uid))
			return "Item doesn't exist.";

		let currItem = this._nominees.get(uid);
		if(!currItem)
			return "Failed to get item.";

		if(currItem.nominator != nominatorID && !admin)
			return "You do not have permission to remove that item.";

		return undefined;
	}

	removeItem(uid: string, nominatorID: string, admin: boolean) {

		if(this._isVoting)
			return "Items cannot be removed while the poll is voting.";

		let res = this.canRemoveItem(nominatorID, uid, admin);
		if(res) return res;

		this._nominees.delete(uid);
		this.saveState();

		return undefined;
	}

	getItem(uid: string) : ItemType | undefined {

		if(!this._nominees.has(uid))
			return undefined;

		return this._nominees.get(uid)?.item;

	}

	getNomineeList() : Array<ItemType> {

		return Array.from(this._nominees.values()).map((internalItem) => {
			return internalItem.item;
		});

	}

	setVoteTime(time: Date) {

		let offset = this._endTime.getTime() - this._voteTime.getTime();

		this._voteTime = time;
		this.saveState();
		this.updateVoteTimeout();

		this.setEndTime(new Date(this._voteTime.getTime() + offset));
	}

	setEndTime(time: Date) {

		this._endTime = time;
		this.saveState();
		this.updateEndTimeout();

	}

	private updateVoteTimeout() {

		let timeToVote = this._voteTime.getTime() - Date.now();

		if(this._voteTimeout)
			Lt.clearTimeout(this._voteTimeout);

		this._voteTimeout = Lt.setTimeout(this.onVoteTimeout, timeToVote);

	}

	private updateEndTimeout() {

		let timeToEnd = this._endTime.getTime() - Date.now();

		if(this._endTimeout)
			Lt.clearTimeout(this._endTimeout);

		this._endTimeout = Lt.setTimeout(this.onEndTimeout, timeToEnd);

	}

	setVote(userID: string, ranks: Array<string>) {

		this._votes.set(userID, ranks);
		this.saveState();

	}

	doBordaCount() : Map<string, number> {

		let outMap = new Map<string, number>();

		this._votes.forEach((rankList) => {

			rankList.forEach((itemUID, index) => {

				if(!outMap.has(itemUID))
					outMap.set(itemUID, 0);

				let pointValue = this._nominees.size - (index + 1);
				outMap.set(itemUID, (outMap.get(itemUID) ?? 0) + pointValue);

			});

		});

		return outMap;
	}

}

// Assisted with basic coding tools ========================================================
function sortMapToArray(map: Map<string, number>) {
  // Create an array of key-value pairs from the map
  const entries = Array.from(map);

  // Sort the array based on the ranking values
  entries.sort((a, b) => b[1] - a[1]);

  // Extract the keys (IDs) into a new array
  const ids = entries.map(([id]) => id);

  return ids;
} // ===========================================================================

// Aided with basic GitHub coding tools (GPT-4) on 2025-01-26
// VS Code extension to monitor container logs for VS Code CLI updates
// Provides GUI notifications and one-click approval for updates

import * as vscode from 'vscode';
import { exec } from 'child_process';
import { promisify } from 'util';

const execAsync = promisify(exec);

interface UpdateStatus {
  updateAvailable: boolean;
  installedVersion?: string;
  candidateVersion?: string;
  timestamp: Date;
}

export function activate(context: vscode.ExtensionContext) {
  console.log('VS Code Container Updater extension is now active');

  const updater = new ContainerUpdater(context);

  // Register commands
  const checkCommand = vscode.commands.registerCommand('vscode-container-updater.checkUpdates', () => {
    updater.checkForUpdates();
  });

  const approveCommand = vscode.commands.registerCommand('vscode-container-updater.approveUpdate', () => {
    updater.approveUpdate();
  });

  const configureCommand = vscode.commands.registerCommand('vscode-container-updater.configure', () => {
    updater.showConfiguration();
  });

  context.subscriptions.push(checkCommand, approveCommand, configureCommand);

  // Start monitoring if auto-check is enabled
  const config = vscode.workspace.getConfiguration('vscode-container-updater');
  if (config.get('autoCheck', true)) {
    updater.startMonitoring();
  }
}

class ContainerUpdater {
  private context: vscode.ExtensionContext;
  private statusBarItem: vscode.StatusBarItem;
  private monitoringInterval?: NodeJS.Timeout;
  private lastUpdateStatus: UpdateStatus = { updateAvailable: false, timestamp: new Date() };

  constructor(context: vscode.ExtensionContext) {
    this.context = context;

    // Create status bar item
    this.statusBarItem = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Right, 100);
    this.statusBarItem.command = 'vscode-container-updater.checkUpdates';
    this.statusBarItem.text = '$(cloud-download) Container Updates';
    this.statusBarItem.tooltip = 'Check for VS Code container updates';
    this.statusBarItem.show();

    context.subscriptions.push(this.statusBarItem);
  }

  startMonitoring() {
    const config = vscode.workspace.getConfiguration('vscode-container-updater');
    const intervalSeconds = config.get('checkInterval', 300); // Default 5 minutes

    // Initial check
    this.checkForUpdates();

    // Set up periodic checking
    this.monitoringInterval = setInterval(() => {
      this.checkForUpdates();
    }, intervalSeconds * 1000);

    vscode.window.showInformationMessage('Container update monitoring started');
  }

  stopMonitoring() {
    if (this.monitoringInterval) {
      clearInterval(this.monitoringInterval);
      this.monitoringInterval = undefined;
    }
  }

  async checkForUpdates() {
    try {
      const config = vscode.workspace.getConfiguration('vscode-container-updater');
      const containerName = config.get('containerName', 'vscode-server-tunnel');

      // Check if container is running
      const isRunning = await this.isContainerRunning(containerName);
      if (!isRunning) {
        this.updateStatusBar('Container not running', '$(warning)');
        return;
      }

      // Check container logs for update notifications
      const updateStatus = await this.parseContainerLogs(containerName);

      if (updateStatus.updateAvailable && !this.lastUpdateStatus.updateAvailable) {
        // New update detected
        this.showUpdateNotification(updateStatus);
      }

      this.lastUpdateStatus = updateStatus;
      this.updateStatusBar(
        updateStatus.updateAvailable ? 'Update Available!' : 'Up to date',
        updateStatus.updateAvailable ? '$(warning)' : '$(check)'
      );

    } catch (error) {
      console.error('Error checking for updates:', error);
      this.updateStatusBar('Check failed', '$(error)');
    }
  }

  private async isContainerRunning(containerName: string): Promise<boolean> {
    try {
      const cmd = 'docker ps --format "{{.Names}}" | grep "^' + containerName + '$"';
      const { stdout } = await execAsync(cmd);
      return stdout.trim() === containerName;
    } catch {
      return false;
    }
  }

  private async parseContainerLogs(containerName: string): Promise<UpdateStatus> {
    try {
      // Get recent logs (last 50 lines)
      const cmd = 'docker logs --tail 50 ' + containerName + ' 2>&1';
      const { stdout } = await execAsync(cmd);

      // Look for update notification pattern
      const updatePattern = /Update available for VS Code CLI \(installed: ([^,]+), candidate: ([^)]+)\)/;
      const match = stdout.match(updatePattern);

      if (match) {
        return {
          updateAvailable: true,
          installedVersion: match[1],
          candidateVersion: match[2],
          timestamp: new Date()
        };
      }

      return { updateAvailable: false, timestamp: new Date() };
    } catch (error) {
      console.error('Error parsing container logs:', error);
      return { updateAvailable: false, timestamp: new Date() };
    }
  }

  private showUpdateNotification(updateStatus: UpdateStatus) {
    const message = 'VS Code CLI update available: ' + updateStatus.installedVersion + ' -> ' + updateStatus.candidateVersion;

    vscode.window.showWarningMessage(
      message,
      'Approve Update',
      'Check Later',
      'Stop Monitoring'
    ).then((selection: string | undefined) => {
      switch (selection) {
        case 'Approve Update':
          this.approveUpdate();
          break;
        case 'Stop Monitoring':
          this.stopMonitoring();
          break;
        // 'Check Later' - do nothing
      }
    });
  }

  async approveUpdate() {
    try {
      const config = vscode.workspace.getConfiguration('vscode-container-updater');
      const containerName = config.get('containerName', 'vscode-server-tunnel');

      // Create approval file in container
      const approvalFile = '$HOME/APPROVE_CODE_UPDATE';
      const cmd = 'docker exec ' + containerName + ' bash -c "touch ' + approvalFile + '"';
      await execAsync(cmd);

      vscode.window.showInformationMessage(
        'Update approved! The container will install the update on the next check cycle.',
        'Check Status'
      ).then((selection: string | undefined) => {
        if (selection === 'Check Status') {
          this.checkForUpdates();
        }
      });

    } catch (error) {
      const errorMsg = 'Failed to approve update: ' + String(error);
      vscode.window.showErrorMessage(errorMsg);
    }
  }

  private updateStatusBar(text: string, icon: string) {
    this.statusBarItem.text = icon + ' ' + text;
    this.statusBarItem.tooltip = 'Container Updates: ' + text;
  }

  showConfiguration() {
    vscode.commands.executeCommand('workbench.action.openSettings', 'vscode-container-updater');
  }

  dispose() {
    this.stopMonitoring();
    this.statusBarItem.dispose();
  }
}

export function deactivate() {
  // Cleanup is handled by dispose methods
}

