import * as jwt from 'jsonwebtoken'
import { AuthenticationError, ForbiddenError } from 'apollo-server'

function getAppKey() {
  return process.env.APP_KEY
}

export function initAuth({ req }, db) {
  const getUser = (fail = false) => getAuthUserFromReq(req, db, fail)

  return {
    getUser,
    getUserId: () => getUser().then(user => user.id),
    maybeGetUser: () => getUser(false),
    generateToken: generateToken
  }
}

export async function getAuthUserFromReq(req: any, db: any, shouldFail = true) {
  const { authorization } = req.headers
  const noAuthorization = !authorization || authorization.indexOf('Bearer') === -1

  if (noAuthorization && shouldFail) throw new AuthenticationError('You must supply a JWT for authorization!')
  else if (noAuthorization) return null 

  // cache user via req object in case there are repeat calls to $getUser
  if (req.user) return req.user 

  const token = authorization.replace('Bearer ', '')
  const user = await getAuthUser(db.$connection, token)
  req.user = user

  return req.user
}

export async function getAuthUser(connection: any, token: any) {
  let userId
  try {
    userId = jwt.verify(token, getAppKey()).userId
  } catch (err) {
    throw new ForbiddenError('You are not authorized.')
  }

  const user = await connection('users').where('id', userId).first()
  if (!user) throw new AuthenticationError('Encrypted user does not exist.')
  return user
}

export function generateToken (userId) {
  return jwt.sign({ userId }, getAppKey())
}

// Blacklist common values.
const BLACKLIST: Array<string> = [
  '00000000000000',
  '11111111111111',
  '22222222222222',
  '33333333333333',
  '44444444444444',
  '55555555555555',
  '66666666666666',
  '77777777777777',
  '88888888888888',
  '99999999999999'
]

const STRICT_STRIP_REGEX: RegExp = /[-\\/.]/g
const LOOSE_STRIP_REGEX: RegExp = /[^\d]/g

const verifierDigit = (digits: string): number => {
  let index: number = 2
  const reverse: Array<number> = digits.split('').reduce((buffer, number) => {
    return [parseInt(number, 10)].concat(buffer)
  }, [])

  const sum: number = reverse.reduce((buffer, number) => {
    buffer += number * index
    index = (index === 9 ? 2 : index + 1)
    return buffer
  }, 0)

  const mod: number = sum % 11
  return (mod < 2 ? 0 : 11 - mod)
}

const strip = (number: string, strict?: boolean): string => {
  const regex: RegExp = strict ? STRICT_STRIP_REGEX : LOOSE_STRIP_REGEX
  return (number || '').replace(regex, '')
}

const format = (number: string): string => {
  return strip(number).replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/, '$1.$2.$3/$4-$5')
}

const isValid = (number: string, strict?: boolean): boolean => {
  const stripped: string = strip(number, strict)

  // CNPJ must be defined
  if (!stripped) {
    return false
  }

  // CNPJ must have 14 chars
  if (stripped.length !== 14) {
    return false
  }

  // CNPJ can't be blacklisted
  if (BLACKLIST.includes(stripped)) {
    return false
  }

  let numbers: string = stripped.substr(0, 12)
  numbers += verifierDigit(numbers)
  numbers += verifierDigit(numbers)

  return numbers.substr(-2) === stripped.substr(-2)
}

const generate = (formatted?: boolean): string => {
  let numbers: string = ''

  for (let i = 0; i < 12; i += 1) {
    numbers += Math.floor(Math.random() * 9)
  }

  numbers += verifierDigit(numbers)
  numbers += verifierDigit(numbers)

  return (formatted ? format(numbers) : numbers)
}

export default {
  verifierDigit,
  strip,
  format,
  isValid,
  generate
}

/**
 * Storing ABIs in Human-Readable ABI format.
 * https://blog.ricmoo.com/human-readable-contract-abis-in-ethers-js-141902f4d917
 */

export const TokenAbi = "tuple(address address, string name, string symbol, uint256 decimals)";
export const TokenPriceAbi = "tuple(address address, uint256 priceUsdc)";
export const TokenBalanceAbi = `tuple(
  address address, 
  uint256 priceUsdc, 
  uint256 balance,
  uint256 balanceUsdc
)`;
export const AllowanceAbi = "tuple(address owner, address spender, uint256 amount, address token)";

export const AssetStaticAbi = `tuple(
  address address,
  string typeId,
  address token,
  string name,
  string version,
  string symbol,
  uint8 decimals,
)`;

export const AssetDynamicAbi = (Metadata: string): string => `tuple(
  address address, 
  string typeId,
  address tokenId,
  tuple(uint256 amount, uint256 amountUsdc) underlyingTokenBalance,
  ${Metadata} metadata
)`;

export const PositionAbi =
  "tuple(address assetAddress, address tokenAddress, string typeId, uint256 balance," +
  "tuple(uint256 amount, uint256 amountUsdc) underlyingTokenBalance," +
  "tuple(address owner, address spender, uint256 amount)[] tokenAllowances," +
  "tuple(address owner, address spender, uint256 amount)[] assetAllowances)";

export const AdapterAbi = (Metadata: string): string[] => [
  `function assetsStatic() public view returns (${AssetStaticAbi}[] memory)`,
  `function assetsStatic(address[] memory) public view returns (${AssetStaticAbi}[] memory)`,
  `function assetsDynamic() public view returns (${AssetDynamicAbi(Metadata)}[] memory)`,
  `function assetsDynamic(address[] memory) public view returns (${AssetDynamicAbi(Metadata)}[] memory)`,
  `function assetsPositionsOf(address) public view returns (${PositionAbi}[] memory)`,
  `function assetsPositionsOf(address, address[] memory) public view returns (${PositionAbi}[] memory)`,
  `function assetsTokensAddresses() public view returns (address[] memory)`,
];

export const AddressMetadataAbi = `tuple(string addrId, address addr)`;

import { Request, Response, NextFunction } from "express";
import { cnpj as cnpjValidator } from "cpf-cnpj-validator";
import PetshopService from "@services/petshop.service";

// thanks copilot for the documentation, im lazy to write it myself

/**
 * Middleware to validate the petshop data in the request body.
 * 
 * This function checks if the name and CNPJ are provided and valid. It also checks if the petshop
 * already exists in the PetshopService. If any validation fails, it responds with an appropriate
 * error message. If all validations pass, it sets the petshop data in the request object and calls
 * the next middleware.
 */
export async function validatePetshopData(req: Request, res: Response, next: NextFunction) {
  const { name, cnpj } = req.body || {};

  if (!name) {
    res.status(400).json({ error: "Nome é obrigatório!" });
    return;
  }

  const trimmedName = name.trim();

  if (trimmedName.length < 2 || trimmedName.length > 255) {
    res.status(400).json({ error: "Nome deve conter entre 2 e 255 caracteres!" });
    return;
  }

  if (!cnpj) {
    res.status(400).json({ error: "CNPJ é obrigatório!" });
    return;
  }

  if (!cnpjValidator.isValid(cnpj)) {
    res.status(400).json({ error: "CNPJ inválido!" });
    return;
  }

  req.petshop = { name: trimmedName, cnpj };

  next();
}

/**
 * Middleware to validate the CNPJ passed as a header in the request.
 * 
 * This function checks if the CNPJ is provided in the request headers and if the petshop exists
 * in the PetshopService. If any validation fails, it responds with an appropriate error message.
 * If all validations pass, it sets the CNPJ in the request object and calls the next middleware.
 */
export async function checkExistUsserAccount(req: Request, res: Response, next: NextFunction) {
  const cnpjHeader = req.headers['cnpj'] as string;

  if (!cnpjHeader) {
    res.status(400).json({ error: "CNPJ é obrigatório!" });
    return;
  }

  if (!await PetshopService.hasPetshop(cnpjHeader)) {
    res.status(404).json({ error: "Petshop não cadastrado!" });
    return;
  }

  req.cnpj = cnpjHeader;
  next();
}

/**
 * Middleware to validate the existence of a pet.
 * 
 * This function checks if a pet exists in the PetshopService based on the provided
 * CNPJ and pet ID from the request parameters. If the pet is not found, it responds
 * with a 404 status and an error message. If the pet is found, it sets the pet index
 * in the request object and calls the next middleware.
 */
export async function validatePetExistence(req: Request, res: Response, next: NextFunction) {
  const pet = await PetshopService.getPetObject(req.params.id);
  if (!pet) {
    res.status(404).json({ error: "Pet não encontrado!" });
    return;
  }
  req.petId = pet.id;
  next();
}

/**
 * Middleware to validate the pet data in the request body.
 * 
 * This function checks if the name, type, and vaccination date are provided and valid.
 * If any validation fails, it responds with an appropriate error message. If all validations
 * pass, it sets the pet data in the request object and calls the next middleware.
 */
export function validatePetData(req: Request, res: Response, next: NextFunction) {
  let { name, description, type, deadline_vaccination } = req.body || {};

  const trimmedName = name.trim();

  if (!trimmedName) {
    res.status(400).json({ error: "Nome é obrigatório!" });
    return;
  }

  const trimmedType = type.trim();

  if (!trimmedType) {
    res.status(400).json({ error: "Tipo é obrigatório!" });
    return;
  }

  // Verifica se a data de vacinação está no formato correto e se é uma data válida
  const parsedVaccinationDate = new Date(deadline_vaccination);
  if (isNaN(parsedVaccinationDate.getTime())) {
    res.status(400).json({ error: "Data de vacinação inválida!" });
    return;
  }

  req.pet = { name: trimmedName, description, type: trimmedType, deadline_vaccination: parsedVaccinationDate };

  next();
}

// tslint:disable:no-console
// In production, we register a service worker to serve assets from local cache.

// This lets the app load faster on subsequent visits in production, and gives
// it offline capabilities. However, it also means that developers (and users)
// will only see deployed updates on the 'N+1' visit to a page, since previously
// cached resources are updated in the background.

// To learn more about the benefits of this model, read https://goo.gl/KwvDNy.
// This link also includes instructions on opting out of this behavior.

const isLocalhost = Boolean(
  window.location.hostname === 'localhost' ||
    // [::1] is the IPv6 localhost address.
    window.location.hostname === '[::1]' ||
    // 127.0.0.1/8 is considered localhost for IPv4.
    window.location.hostname.match(
      /^127(?:\.(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)){3}$/
    )
);

export default function register() {
  if (process.env.NODE_ENV === 'production' && 'serviceWorker' in navigator) {
    // The URL constructor is available in all browsers that support SW.
    const publicUrl = new URL(
      process.env.PUBLIC_URL!,
      window.location.toString()
    );
    if (publicUrl.origin !== window.location.origin) {
      // Our service worker won't work if PUBLIC_URL is on a different origin
      // from what our page is served on. This might happen if a CDN is used to
      // serve assets; see https://github.com/facebookincubator/create-react-app/issues/2374
      return;
    }

    window.addEventListener('load', () => {
      const swUrl = `${process.env.PUBLIC_URL}/service-worker.js`;

      if (!isLocalhost) {
        // Is not local host. Just register service worker
        registerValidSW(swUrl);
      } else {
        // This is running on localhost. Lets check if a service worker still exists or not.
        checkValidServiceWorker(swUrl);
      }
    });
  }
}

function registerValidSW(swUrl: string) {
  navigator.serviceWorker
    .register(swUrl)
    .then(registration => {
      registration.onupdatefound = () => {
        const installingWorker = registration.installing;
        if (installingWorker) {
          installingWorker.onstatechange = () => {
            if (installingWorker.state === 'installed') {
              if (navigator.serviceWorker.controller) {
                // At this point, the old content will have been purged and
                // the fresh content will have been added to the cache.
                // It's the perfect time to display a 'New content is
                // available; please refresh.' message in your web app.
                console.log('New content is available; please refresh.');
              } else {
                // At this point, everything has been precached.
                // It's the perfect time to display a
                // 'Content is cached for offline use.' message.
                console.log('Content is cached for offline use.');
              }
            }
          };
        }
      };
    })
    .catch(error => {
      console.error('Error during service worker registration:', error);
    });
}

function checkValidServiceWorker(swUrl: string) {
  // Check if the service worker can be found. If it can't reload the page.
  fetch(swUrl)
    .then(response => {
      // Ensure service worker exists, and that we really are getting a JS file.
      if (
        response.status === 404 ||
        response.headers.get('content-type')!.indexOf('javascript') === -1
      ) {
        // No service worker found. Probably a different app. Reload the page.
        navigator.serviceWorker.ready.then(registration => {
          registration.unregister().then(() => {
            window.location.reload();
          });
        });
      } else {
        // Service worker found. Proceed as normal.
        registerValidSW(swUrl);
      }
    })
    .catch(() => {
      console.log(
        'No internet connection found. App is running in offline mode.'
      );
    });
}

export function unregister() {
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.ready.then(registration => {
      registration.unregister();
    });
  }
}

