// Aided with basic GitHub coding tools

/**
 * Docker Service - Manages Docker containers and Docker Compose operations
 * Quản lý Docker containers và các thao tác Docker Compose
 */

import { Tool } from '@modelcontextprotocol/sdk/types.js';
import { Service } from './base-service.js';
import { spawn, exec } from 'child_process';
import { promisify } from 'util';
import * as path from 'path';
import * as fs from 'fs/promises';

const execAsync = promisify(exec);

/**
 * Docker Container Status
 * Trạng thái của Docker container
 */
export interface ContainerStatus {
    name: string;
    status: 'running' | 'stopped' | 'paused' | 'restarting' | 'removing' | 'created' | 'exited' | 'dead';
    health: 'healthy' | 'unhealthy' | 'starting' | 'none';
    uptime: string;
    ports: string[];
    image: string;
}

/**
 * Docker Compose Service Definition
 * Định nghĩa service trong Docker Compose
 */
export interface ComposeService {
    name: string;
    image: string;
    ports: string[];
    volumes: string[];
    environment: Record<string, string>;
    healthCheck?: {
        test: string[];
        interval: string;
        timeout: string;
        retries: number;
    };
}

/**
 * Docker Service Implementation
 * Implements Docker container management operations
 */
export class DockerService implements Service {
    readonly namespace = 'docker';
    readonly name = 'Docker Management Service';
    readonly version = '1.0.0';
    readonly description = 'Manages Docker containers, images, and Docker Compose operations';

    private composePath: string;
    private projectName: string;

    constructor(composePath?: string, projectName?: string) {
        this.composePath = composePath || path.join(process.cwd(), 'docker-compose.yml');
        this.projectName = projectName || 'mcp';
    }

    /**
     * List all available Docker management tools
     * Liệt kê tất cả các công cụ quản lý Docker
     */
    async listTools(): Promise<{ tools: Tool[] }> {
        return {
            tools: [
                {
                    name: 'docker_ps',
                    description: 'List all Docker containers with their status',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            all: {
                                type: 'boolean',
                                description: 'Show all containers (default: false - only running)',
                                default: false
                            }
                        }
                    }
                },
                {
                    name: 'docker_compose_up',
                    description: 'Start Docker Compose services',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            services: {
                                type: 'array',
                                items: { type: 'string' },
                                description: 'Specific services to start (optional - all services if not specified)'
                            },
                            detached: {
                                type: 'boolean',
                                description: 'Run in detached mode',
                                default: true
                            },
                            build: {
                                type: 'boolean',
                                description: 'Build images before starting',
                                default: false
                            }
                        }
                    }
                },
                {
                    name: 'docker_compose_down',
                    description: 'Stop and remove Docker Compose services',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            volumes: {
                                type: 'boolean',
                                description: 'Remove volumes as well',
                                default: false
                            },
                            removeImages: {
                                type: 'string',
                                enum: ['all', 'local', 'none'],
                                description: 'Remove images (all, local, or none)',
                                default: 'none'
                            }
                        }
                    }
                },
                {
                    name: 'docker_compose_restart',
                    description: 'Restart Docker Compose services',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            services: {
                                type: 'array',
                                items: { type: 'string' },
                                description: 'Specific services to restart (optional)'
                            }
                        }
                    }
                }, {
                    name: 'docker_logs',
                    description: 'Get logs from Docker containers',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            container: {
                                type: 'string',
                                description: 'Container name or ID'
                            },
                            tail: {
                                type: 'number',
                                description: 'Number of lines to show from the end of logs',
                                default: 100
                            },
                            follow: {
                                type: 'boolean',
                                description: 'Follow log output',
                                default: false
                            }
                        },
                        required: ['container']
                    }
                },
                {
                    name: 'docker_health_check',
                    description: 'Check health status of all services',
                    inputSchema: {
                        type: 'object',
                        properties: {}
                    }
                }, {
                    name: 'docker_exec',
                    description: 'Execute command in running container',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            container: {
                                type: 'string',
                                description: 'Container name or ID'
                            },
                            command: {
                                type: 'string',
                                description: 'Command to execute'
                            },
                            interactive: {
                                type: 'boolean',
                                description: 'Run in interactive mode',
                                default: false
                            }
                        },
                        required: ['container', 'command']
                    }
                },
                {
                    name: 'docker_stats',
                    description: 'Get resource usage statistics for containers',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            containers: {
                                type: 'array',
                                items: { type: 'string' },
                                description: 'Specific containers to monitor (optional - all if not specified)'
                            }
                        }
                    }
                }
            ]
        };
    }

    /**
     * Execute Docker management tools
     * Thực thi các công cụ quản lý Docker
     */
    async callTool(name: string, args: any): Promise<any> {
        try {
            switch (name) {
                case 'docker_ps':
                    return await this.listContainers(args.all || false);

                case 'docker_compose_up':
                    return await this.composeUp(args.services, args.detached !== false, args.build || false);

                case 'docker_compose_down':
                    return await this.composeDown(args.volumes || false, args.removeImages || 'none');

                case 'docker_compose_restart':
                    return await this.composeRestart(args.services);

                case 'docker_logs':
                    return await this.getLogs(args.container, args.tail || 100, args.follow || false);

                case 'docker_health_check':
                    return await this.healthCheck();

                case 'docker_exec':
                    return await this.execCommand(args.container, args.command, args.interactive || false);

                case 'docker_stats':
                    return await this.getStats(args.containers);

                default:
                    throw new Error(`Unknown Docker tool: ${name}`);
            }
        } catch (error) {
            throw new Error(`Docker tool '${name}' failed: ${error instanceof Error ? error.message : String(error)}`);
        }
    }

  /**
   * List Docker containers
   * Liệt kê các Docker containers
   */  private async listContainers(all: boolean = false): Promise<{ containers: ContainerStatus[] }> {
        const command = all ? 'docker ps -a --format "{{.Names}}\t{{.Status}}\t{{.Ports}}\t{{.Image}}"'
            : 'docker ps --format "{{.Names}}\t{{.Status}}\t{{.Ports}}\t{{.Image}}"';

        const { stdout } = await execAsync(command);
        const lines = stdout.trim().split('\n');

        const containers: ContainerStatus[] = [];
        for (const line of lines) {
            if (line.trim()) {
                const parts = line.split('\t');
                if (parts.length >= 4) {
                    const [name, status, ports, image] = parts;

                    // Get health status
                    let health: ContainerStatus['health'] = 'none';
                    try {
                        const { stdout: healthOutput } = await execAsync(`docker inspect --format='{{.State.Health.Status}}' ${name.trim()}`);
                        const healthStatus = healthOutput.trim();
                        if (healthStatus && healthStatus !== '<no value>') {
                            health = healthStatus as ContainerStatus['health'];
                        }
                    } catch {
                        // Health check not available
                    }

                    containers.push({
                        name: name.trim(),
                        status: this.parseContainerStatus(status.trim()),
                        health,
                        uptime: status.trim(),
                        ports: ports ? ports.split(',').map(p => p.trim()) : [],
                        image: image.trim()
                    });
                }
            }
        }

        return { containers };
    }

    /**
     * Start Docker Compose services
     * Khởi động các dịch vụ Docker Compose
     */
    private async composeUp(services?: string[], detached: boolean = true, build: boolean = false): Promise<{ success: boolean; message: string; output: string }> {
        let command = `docker compose -f "${this.composePath}"`;

        if (build) {
            command += ' up --build';
        } else {
            command += ' up';
        }

        if (detached) {
            command += ' -d';
        }

        if (services && services.length > 0) {
            command += ` ${services.join(' ')}`;
        }

        try {
            const { stdout, stderr } = await execAsync(command);
            return {
                success: true,
                message: `Docker Compose services started successfully`,
                output: stdout + stderr
            };
        } catch (error: any) {
            return {
                success: false,
                message: `Failed to start Docker Compose services: ${error.message}`,
                output: error.stdout + error.stderr
            };
        }
    }

    /**
     * Stop Docker Compose services
     * Dừng các dịch vụ Docker Compose
     */
    private async composeDown(volumes: boolean = false, removeImages: string = 'none'): Promise<{ success: boolean; message: string; output: string }> {
        let command = `docker compose -f "${this.composePath}" down`;

        if (volumes) {
            command += ' -v';
        }

        if (removeImages !== 'none') {
            command += ` --rmi ${removeImages}`;
        }

        try {
            const { stdout, stderr } = await execAsync(command);
            return {
                success: true,
                message: 'Docker Compose services stopped successfully',
                output: stdout + stderr
            };
        } catch (error: any) {
            return {
                success: false,
                message: `Failed to stop Docker Compose services: ${error.message}`,
                output: error.stdout + error.stderr
            };
        }
    }

    /**
     * Restart Docker Compose services
     * Khởi động lại các dịch vụ Docker Compose
     */
    private async composeRestart(services?: string[]): Promise<{ success: boolean; message: string; output: string }> {
        let command = `docker compose -f "${this.composePath}" restart`;

        if (services && services.length > 0) {
            command += ` ${services.join(' ')}`;
        }

        try {
            const { stdout, stderr } = await execAsync(command);
            return {
                success: true,
                message: 'Docker Compose services restarted successfully',
                output: stdout + stderr
            };
        } catch (error: any) {
            return {
                success: false,
                message: `Failed to restart Docker Compose services: ${error.message}`,
                output: error.stdout + error.stderr
            };
        }
    }

    /**
     * Get container logs
     * Lấy logs từ container
     */
    private async getLogs(container: string, tail: number = 100, follow: boolean = false): Promise<{ logs: string; container: string }> {
        let command = `docker logs --tail ${tail}`;

        if (follow) {
            command += ' -f';
        }

        command += ` ${container}`;

        try {
            const { stdout, stderr } = await execAsync(command);
            return {
                container,
                logs: stdout + stderr
            };
        } catch (error: any) {
            throw new Error(`Failed to get logs for container ${container}: ${error.message}`);
        }
    }

    /**
     * Health check for all services
     * Kiểm tra sức khỏe của tất cả các dịch vụ
     */
    private async healthCheck(): Promise<{ services: Array<{ name: string; status: string; health: string }> }> {
        const { containers } = await this.listContainers(false);

        const services = containers.map(container => ({
            name: container.name,
            status: container.status,
            health: container.health
        }));

        return { services };
    }

    /**
     * Execute command in container
     * Thực thi lệnh trong container
     */
    private async execCommand(container: string, command: string, interactive: boolean = false): Promise<{ output: string; container: string; command: string }> {
        let dockerCommand = 'docker exec';

        if (interactive) {
            dockerCommand += ' -it';
        }

        dockerCommand += ` ${container} ${command}`;

        try {
            const { stdout, stderr } = await execAsync(dockerCommand);
            return {
                container,
                command,
                output: stdout + stderr
            };
        } catch (error: any) {
            throw new Error(`Failed to execute command in container ${container}: ${error.message}`);
        }
    }

    /**
     * Get container resource statistics
     * Lấy thống kê tài nguyên của container
     */
    private async getStats(containers?: string[]): Promise<{ stats: string }> {
        let command = 'docker stats --no-stream --format "table {{.Container}}\t{{.CPUPerc}}\t{{.MemUsage}}\t{{.NetIO}}\t{{.BlockIO}}"';

        if (containers && containers.length > 0) {
            command += ` ${containers.join(' ')}`;
        }

        try {
            const { stdout } = await execAsync(command);
            return { stats: stdout };
        } catch (error: any) {
            throw new Error(`Failed to get container stats: ${error.message}`);
        }
    }

    /**
     * Parse container status from Docker output
     * Phân tích trạng thái container từ output của Docker
     */
    private parseContainerStatus(status: string): ContainerStatus['status'] {
        const statusLower = status.toLowerCase();

        if (statusLower.includes('up')) return 'running';
        if (statusLower.includes('exited')) return 'exited';
        if (statusLower.includes('created')) return 'created';
        if (statusLower.includes('restarting')) return 'restarting';
        if (statusLower.includes('removing')) return 'removing';
        if (statusLower.includes('paused')) return 'paused';
        if (statusLower.includes('dead')) return 'dead';

        return 'stopped';
    }

    /**
     * Check if Docker is available
     * Kiểm tra xem Docker có khả dụng không
     */
    async isDockerAvailable(): Promise<boolean> {
        try {
            await execAsync('docker --version');
            return true;
        } catch {
            return false;
        }
    }

    /**
     * Check if Docker Compose is available
     * Kiểm tra xem Docker Compose có khả dụng không
     */
    async isDockerComposeAvailable(): Promise<boolean> {
        try {
            await execAsync('docker compose version');
            return true;
        } catch {
            return false;
        }
    }
}

import { AxiosResponse } from 'axios';
import { readJson, writeFile, writeJson } from 'fs-extra';
import { EOL } from 'os';
import * as path from 'path';
import * as semver from 'semver';
import { EachApiCallNextApiUrlParser, EachApiCallOptions, eachApiCalls } from './utils';


// Interfaces
interface GithubIssue {
    id: string;
    url: string;
    html_url: string;
    number: number;
    state: 'open' | 'closed';
    labels: {
        id: number;
        name: string;
    }[];
    title: string;
    body: string;
    user: {
        login: string;
        url: string;
        avatar_url: string;
        html_url: string;
        type: 'User';
    };
    milestone?: {
        id: string;
        number: number;
        title: string;
        description: string;
        open_issues: number;
        closed_issues: number;
        created_at: string;
        closed_at: string | null;
        due_on: string;
    };
    pull_request?: {
        url: string;
        html_url: string;
    };
    closed_at: string | null;
    created_at: string;
}


type IssueType = 'feature' | 'enhancement' | 'bug' | 'doc' | 'art';
const allIssueTypes: IssueType[] = ['feature', 'enhancement', 'bug', 'doc', 'art'];
const issueTypeEmojiMap = {
    feature: '💡',
    enhancement: '🛠',
    bug: '🔥',
    doc: '📖',
    art: '🎨',
};


interface ChangelogItem {
    types?: IssueType[];
    title: string;
    number: number;
    htmlUrl: string;
}


interface ChangelogOfVersion {
    version: string;
    items: ChangelogItem[];
}


// General functions
const githubNextApiUrlParser: EachApiCallNextApiUrlParser =
    (response: AxiosResponse): string | null => {
        const linkHeader = response.headers.link;

        if (!linkHeader) {
            return null;
        }

        // 'Pages' header values like "<https://some-next-url> rel=next, <https://some-prev-url> rel=prev".
        const pages = (linkHeader as string).split(',');

        if (pages[0] && /rel="next"/.test(pages[0])) {
            const matches = pages[0].match(/<(.+)>/);

            if (matches && matches[1]) {
                return matches[1];
            } else {
                return null;
            }
        }

        return null;
    };


// Application functions
async function getAllPullRequestsForMilestone(milestone: string): Promise<GithubIssue[]> {
    const issues: GithubIssue[] = [];
    const options: EachApiCallOptions = {
        requestConfig: {
            params: {
                state: 'closed',
                milestone,
            },
            headers: {
                Accept: 'application/vnd.github.v3+json',
                'User-Agent': 'geeks-diary',
            },
        },
        nextApiUrlParser: githubNextApiUrlParser,
    };

    if (process.env.GITHUB_USER && process.env.GITHUB_PASSWORD) {
        options.requestConfig.auth = {
            username: process.env.GITHUB_USER,
            password: process.env.GITHUB_PASSWORD,
        };
    }

    const eachGithubIssueApiCalls = eachApiCalls<GithubIssue[]>(
        'https://api.github.com/repos/seokju-na/geeks-diary/issues',
        options,
    );

    for await (const data of eachGithubIssueApiCalls) {
        issues.push(...data);
    }

    return issues.filter(issue => !!issue.pull_request);
}


function parsePrToChangelogItem(pr: GithubIssue): ChangelogItem {
    const types: IssueType[] = pr.labels.reduce(
        (reduced, label) => allIssueTypes.includes(label.name as IssueType)
            ? reduced.concat(label.name as IssueType)
            : reduced,
        [],
    );

    return {
        types,
        title: pr.title,
        number: pr.number,
        htmlUrl: pr.pull_request.html_url,
    };
}


function getChangelogOfVersion(changelogs: ChangelogOfVersion[], version: string): ChangelogOfVersion | undefined {
    const cleanVersion = semver.clean(version);
    return changelogs.find(changelog => changelog.version === cleanVersion);
}


function updateChangelogs(
    changelogs: ChangelogOfVersion[],
    version: string,
    prs: GithubIssue[],
): ChangelogOfVersion[] {
    const prevChangelog = getChangelogOfVersion(changelogs, version);
    const newChangelog: ChangelogOfVersion = {
        version: semver.clean(version),
        items: prs.map(parsePrToChangelogItem),
    };

    if (prevChangelog) {
        const index = changelogs.indexOf(prevChangelog);

        changelogs[index] = newChangelog;
    } else {
        changelogs.push(newChangelog);
    }

    // Sort desc by version.
    return changelogs.sort((a, b) => {
        if (semver.gt(a.version, b.version)) {
            return -1;
        } else if (semver.lt(a.version, b.version)) {
            return 1;
        } else {
            return 0;
        }
    });
}


function getMarkdownFromChangelogs(changelogs: ChangelogOfVersion[]): string {
    let content = `# Changelog${EOL}${EOL}`;

    content += `(💡=Feature, 🛠=Enhancement, 🔥=Bug, 📖=Document, 🎨=Art)${EOL}${EOL}`;

    for (const changelog of changelogs) {
        content += `## v${changelog.version}${EOL}`;

        for (const item of changelog.items) {
            const link = `[#${item.number}](${item.htmlUrl})`;
            const labels = item.types.reduce((typeStr, type) => typeStr + issueTypeEmojiMap[type], '');

            content += labels
                ? `- ${link} ${labels} ${item.title}`
                : `- ${link} ${item.title}`;

            content += EOL;
        }
    }

    return content;
}


// Main function
async function main(version: string, milestone: string): Promise<void> {
    if (!milestone) {
        throw new Error('You should input \'milestone\'.');
    }

    const prs = await getAllPullRequestsForMilestone(milestone);

    // Read changelogs and update
    const CHANGELOGS_JSON_FILE = path.resolve(__dirname, '../changelogs.json');
    let changelogs: ChangelogOfVersion[] = await readJson(CHANGELOGS_JSON_FILE, { throws: true });

    changelogs = updateChangelogs(changelogs, version, prs);

    await writeJson(CHANGELOGS_JSON_FILE, changelogs);

    // Write changelog markdown.
    const CHANGELOG_MARKDOWN_FILE = path.resolve(__dirname, '../CHANGELOG.md');
    const content = getMarkdownFromChangelogs(changelogs);

    await writeFile(CHANGELOG_MARKDOWN_FILE, content);
}


const appVersion = (require('../src/package.json') as any).version;

main(appVersion, process.argv[2])
    .then(() => process.exit(0))
    .catch((error) => {
        console.error(error);
        process.exit(1);
    });

import yaml from 'js-yaml'
import ml from 'multilines'
import * as os from 'os'

import { LSCConfiguration, LSCLabel, LSCRepository } from './types'
import { mapEntries, mapKeys } from './utils'

/* Constants */

const NUMBER_OF_FREE_TIERS = 5

/**
 * Configuration repository is the repository which LabelSync
 * uses to determine the configuration of the service.
 */
export const getLSConfigRepoName = (account: string) => `${account.toLowerCase()}-labelsync`

/**
 * Configuration file path determines the path of the file in the repositoy
 * that we use to gather configuration information from.
 *
 * It should always be in YAML format.
 */
export const LS_CONFIG_PATH = 'labelsync.yml'

/**
 * Parses a string into a configuration object.
 */
export function parseConfig({
  input,
  isPro,
}: {
  input: string
  isPro: boolean
}): { ok: true; config: LSCConfiguration } | { ok: false; error: string } {
  const rawConfig = yaml.load(input, {})
  const parsedConfig = LSCConfiguration.safeParse(rawConfig)

  if (!parsedConfig.success) {
    return { ok: false, error: parsedConfig.error.message }
  }

  const normalizedConfig = normalizeConfig(parsedConfig.data)
  const validatedConfig = validateConfiguration(normalizedConfig)

  if (!validatedConfig.ok) {
    return { ok: false, error: validatedConfig.error }
  }

  const acceptable = checkPurchase({
    config: validatedConfig.config,
    isPro,
  })

  if (!acceptable.ok) {
    return { ok: false, error: acceptable.error }
  }

  return { ok: true, config: validatedConfig.config }
}

/**
 * Makes sure that the config respects plan limitations..
 */
function checkPurchase({
  config,
  isPro,
}: {
  config: LSCConfiguration
  isPro: boolean
}): { ok: true } | { ok: false; error: string } {
  const numberOfConfiguredRepos = Object.keys(config.repos).length

  if (isPro) {
    return { ok: true }
  }

  /**
   * Report too many configurations.
   */
  if (numberOfConfiguredRepos >= NUMBER_OF_FREE_TIERS) {
    const report = ml`
        | You are trying to configure more repositories than there are available in your plan.
        | Update your current plan to access all the features LabelSync offers.
        `
    return { ok: false, error: report }
  }

  /**
   * Report wildcard configuration.
   */
  if (Object.keys(config.repos).includes('*')) {
    const report = ml`
        | You are trying to configure a wildcard configuration on a free plan.
        | Update your current plan to access all the features LabelSync offers.
        `
    return { ok: false, error: report }
  }

  return { ok: true }
}

/* CONTENT CHECK */

/**
 * Returns configuration if everything seems as expected. Throws otherwise
 * with the error exaplanation.
 */
function validateConfiguration(
  config: LSCConfiguration,
): { ok: true; config: LSCConfiguration } | { ok: false; error: string } {
  /**
   * We accumulate possible errors in all the checks and throw the collection.
   */
  let errors: string[] = []

  /* MISSING SIBLINGS */

  /**
   * All siblings should be defined in the configuration.
   */

  let missingSiblings: { repo: string; sibling: string; label: string }[] = []
  for (const repoName in config.repos) {
    const repoConfig = config.repos[repoName]
    const configuredLabels = Object.keys(repoConfig.labels)

    /* Check every label for unconfigured siblings. */
    for (const label in repoConfig.labels) {
      const siblings = repoConfig.labels[label].siblings ?? []

      for (const sibling of siblings) {
        /* Report unconfigured missing sibling. */
        if (!configuredLabels.includes(sibling)) {
          missingSiblings.push({ repo: repoName, sibling, label })
        }
      }
    }
  }

  if (missingSiblings.length !== 0) {
    const report = ml`
    | Configuration references unconfigured siblings:
    | ${missingSiblings.map((s) => `* \`${s.sibling}\` in ${s.repo}:${s.label}`).join(os.EOL)}
    `
    errors.push(report)
  }

  /* ALIAS SPLITING */

  /**
   * You shouldn't make two new labels aliasing one label.
   */

  let duplicateAliaii: { repo: string; alias: string; labels: string[] }[] = []

  /* Check each repository */
  for (const repoName in config.repos) {
    const repoConfig = config.repos[repoName]

    let aliaiiInRepo: { [alias: string]: string[] } = {}

    /* Check every label for unconfigured siblings. */
    for (const label in repoConfig.labels) {
      const aliaii = repoConfig.labels[label].alias ?? []

      /* Create a map of aliases. */
      for (const alias of aliaii) {
        if (!aliaiiInRepo.hasOwnProperty(alias)) aliaiiInRepo[alias] = []
        aliaiiInRepo[alias].push(label)
      }
    }

    /* Find multiples */
    for (const alias in aliaiiInRepo) {
      if (aliaiiInRepo[alias].length > 1) {
        duplicateAliaii.push({
          repo: repoName,
          alias,
          labels: aliaiiInRepo[alias],
        })
      }
    }
  }

  if (duplicateAliaii.length !== 0) {
    const report = ml`
    | Configuration references same old label twice in alias:
    | ${duplicateAliaii.map((s) => `* \`${s.alias}\` appears in ${s.repo}:${s.labels.join(', ')}`).join(os.EOL)}
    |
    | Each legacy label may only be referenced once in alias.
    `
    errors.push(report)
  }

  /* SELF REFERENCES */

  /**
   * Siblings shouldn't self-reference themselves.
   */

  let selfreferencingSiblings: { repo: string; label: string }[] = []
  for (const repoName in config.repos) {
    const repoConfig = config.repos[repoName]

    /**
     * Check every label if it references itself.
     */
    for (const label in repoConfig.labels) {
      const siblings = repoConfig.labels[label].siblings ?? []

      if (siblings.includes(label)) {
        selfreferencingSiblings.push({ repo: repoName, label })
      }
    }
  }

  if (selfreferencingSiblings.length !== 0) {
    const report = ml`
    | Some of the labels in the configuration reference itself as a sibling:
    | ${selfreferencingSiblings.map((s) => `* \`${s.label}\` in ${s.repo}`).join(os.EOL)}
    `
    errors.push(report)
  }

  /* DESCRIPTION LENGTHS */

  /**
   * Siblings shouldn't self-reference themselves.
   */

  let labelsWithTooLongDescriptions: { repo: string; label: string }[] = []
  for (const repoName in config.repos) {
    const repoConfig = config.repos[repoName]

    /**
     * Check every label if it references itself.
     */
    for (const label in repoConfig.labels) {
      const { description } = repoConfig.labels[label]

      if (description && description.length > 1000) {
        labelsWithTooLongDescriptions.push({ repo: repoName, label })
      }
    }
  }

  if (labelsWithTooLongDescriptions.length !== 0) {
    const report = ml`
     | Some of the labels in the configuration have too long descriptions:
     | ${selfreferencingSiblings.map((s) => `* \`${s.label}\` in ${s.repo}`).join(os.EOL)}

     | The maximum is 1000 characters.
     `
    errors.push(report)
  }

  /**
   * Collect the errors and throw if necessary.
   */

  if (errors.length > 0) {
    return { ok: false, error: errors.join(os.EOL) }
  }

  return { ok: true, config }
}

/**
 * TRANSFORMATIONS
 */

/**
 * Normalizes configuration that's easier to work with.
 */
function normalizeConfig(config: LSCConfiguration): LSCConfiguration {
  const repos = mapEntries(config.repos, fixRepoConfig)
  const lowercaseRepos = mapKeys(repos, (repo) => repo.toLowerCase())

  return {
    ...config,
    repos: lowercaseRepos,
  }
}

function fixRepoConfig(config: LSCRepository): LSCRepository {
  const labels = mapEntries<LSCLabel, LSCLabel>(config.labels, (label) => ({
    ...label,
    color: normalizeColor(label.color),
  }))

  return {
    ...config,
    labels,
  }
}

export function normalizeColor(color: string): string {
  if (color.startsWith('#')) return color.slice(1).toLowerCase()
  return color.toLowerCase()
}

/**
 * Returns a list of repositories in configuration without wildcard config.
 */
export function getPhysicalRepositories(config: LSCConfiguration): string[] {
  return Object.keys(config.repos).filter((repo) => repo !== '*')
}

/**
 * Tells whether the repository is the configuration
 * repository for the account.
 */
export function isConfigRepo(account: string, repo: string): boolean {
  return getLSConfigRepoName(account) === repo.toLowerCase()
}

import { EMPTY, catchError, from, map, mergeMap } from 'rxjs';

import { CommitCompact } from '../../../git-functions/commit.model';
import { repoCompact$ } from '../../../git-functions/repo';

import { RepoCompactWithCommitsByMonths, ReposWithCommitsByMonths } from './repos-with-commits-by-month.model';
import { newCommitsByMonth } from './commits-by-month';
import { gitRepoPaths } from '../../../git-functions/repo-path';

// reposCompactWithCommitsByMonthsInFolderObs returns an Observable that notifies the list of
// RepoCompactWithCommitsByMonths objects representing all the repos in a given folder
export function reposCompactWithCommitsByMonthsInFolderObs(
    folderPath: string,
    fromDate = new Date(0),
    toDate = new Date(Date.now()),
    concurrency = 1,
) {
    const repoPaths = gitRepoPaths(folderPath);
    return from(repoPaths).pipe(
        mergeMap((repoPath) => {
            return newRepoCompactWithCommitsByMonths(repoPath, fromDate, toDate);
        }, concurrency),
    );
}

// newRepoCompactWithCommitsByMonths returns an Observable that notifies a new RepoCompactWithCommitsByMonths
// filled with its commits sorted by date ascending
export function newRepoCompactWithCommitsByMonths(
    repoPath: string,
    fromDate = new Date(0),
    toDate = new Date(Date.now()),
) {
    return repoCompact$(repoPath, fromDate, toDate).pipe(
        map((repoCompact) => {
            const _commitsByMonth = newCommitsByMonth(repoCompact.commits);
            const repo: RepoCompactWithCommitsByMonths = { ...repoCompact, commitsByMonth: _commitsByMonth };
            return repo;
        }),
        catchError((err) => {
            console.error(
                `Error: while reading the commits of repo "${repoPath}" - error:\n ${JSON.stringify(err, null, 2)}`,
            );
            return EMPTY;
        }),
    );
}

// newReposWithCommitsByMonth retuns all the repos that have commits in a given month grouped by month
// #copilot - the entire method has been Aided with basic GitHub coding tools once I have specified the return type
export function newReposWithCommitsByMonth(repos: RepoCompactWithCommitsByMonths[]): ReposWithCommitsByMonths {
    const reposByMonthUnordered = repos.reduce((acc, repo) => {
        Object.keys(repo.commitsByMonth).forEach((yearMonth) => {
            if (!acc[yearMonth]) {
                acc[yearMonth] = [];
            }
            acc[yearMonth].push({
                repoPath: repo.path,
                commits: repo.commitsByMonth[yearMonth].commits,
                authors: Array.from(repo.commitsByMonth[yearMonth].authors),
            });
        });
        return acc;
    }, {} as ReposWithCommitsByMonths);

    const reposByMonthOrdered = Object.keys(reposByMonthUnordered)
        .sort()
        .reduce((obj, key) => {
            obj[key] = reposByMonthUnordered[key];
            return obj;
        }, {} as ReposWithCommitsByMonths);

    const [firstYearMonth, lastYearMonth] = getMinMax(Object.keys(reposByMonthOrdered));
    fillMissingMonths(reposByMonthOrdered, firstYearMonth, lastYearMonth, []);
    return reposByMonthOrdered;
}

// fillMissingMonths fills the missing months in a given ReposWithCommitsByMonths object
// #copilot - the core of the method has been Aided with basic GitHub coding tools
export function fillMissingMonths(
    dict: { [yearMonth: string]: any },
    firstYearMonth: string,
    lastYearMonth: string,
    value: any,
) {
    const firstYear = parseInt(firstYearMonth.split('-')[0]);
    const firstMonth = parseInt(firstYearMonth.split('-')[1]);
    const firstYearMonthAsNumber = yearMonthAsNumber(firstYear, firstMonth);

    const lastYear = parseInt(lastYearMonth.split('-')[0]);
    const lastMonth = parseInt(lastYearMonth.split('-')[1]);
    const lastYearMonthAsNumber = yearMonthAsNumber(lastYear, lastMonth);

    for (let year = firstYear; year <= lastYear; year++) {
        for (let month = 1; month <= 12; month++) {
            const yearMonth = `${year}-${month.toString().padStart(2, '0')}`;
            if (!dict[yearMonth]) {
                if (yearMonthAsNumber(year, month) < firstYearMonthAsNumber) continue;
                if (yearMonthAsNumber(year, month) > lastYearMonthAsNumber) continue;
                dict[yearMonth] = value;
            }
        }
    }
}

function getMinMax(arr: string[]) {
    if (!arr || arr.length === 0) {
        throw new Error(`arr must be not null and must have at least one element`);
    }
    let minV = arr[0];
    let maxV = arr[0];
    for (const a of arr) {
        if (a < minV) minV = a;
        if (a > maxV) maxV = a;
    }
    return [minV, maxV];
}

function yearMonthAsNumber(year: number, month: number) {
    return year * 100 + month;
}

// repoCommitsByMonthRecordsDict returns a dictionary where the repo paths are the keys and the values are the commits grouped by month
export function repoCommitsByMonthRecordsDict(reposByMonths: ReposWithCommitsByMonths) {
    const records: { [repoPath: string]: { [yearMonth: string]: CommitCompact[] } } = {};

    // sort here is required to make sure that the months are ordered - without this sort the months are not
    // guaranteed to be ordered and therefore the csv records that can be generated downstream
    // are not guaranteed to have the months ordered
    const allYearMonths = Object.keys(reposByMonths)
        .sort()
        .reduce((acc, yearMonth) => {
            acc[yearMonth] = [];
            return acc;
        }, {} as { [yearMonth: string]: CommitCompact[] });

    const allReposPaths = Object.values(reposByMonths).reduce((acc, repos) => {
        repos.forEach((repo) => {
            if (!acc.includes(repo.repoPath)) {
                acc.push(repo.repoPath);
            }
        });
        return acc;
    }, [] as string[]);

    allReposPaths.forEach((repoPath) => {
        records[repoPath] = { ...allYearMonths };
    });

    Object.entries(reposByMonths).forEach(([yearMonth, repos]) => {
        repos.forEach((repo) => {
            const rec = records[repo.repoPath];
            rec[yearMonth] = repo.commits;
        });
    });
    return records;
}

// repoCommitsByMonthRecords returns an array of records that contain the repo path and the number of commits for each month
// such records are used to generate the csv file
export function repoCommitsByMonthRecords(reposByMonths: ReposWithCommitsByMonths) {
    const recordDict: { [repoPath: string]: { [yearMonth: string]: number } } = {};
    const _repoCommitsByMonthRecordsDict = repoCommitsByMonthRecordsDict(reposByMonths);

    Object.entries(_repoCommitsByMonthRecordsDict).forEach(([repoPath, repoCommitsByMonth]) => {
        const numOfCommitsByMonth: { [yearMonth: string]: number } = Object.entries(repoCommitsByMonth).reduce(
            (acc, [yearMonth, commits]) => {
                acc[yearMonth] = commits.length;
                return acc;
            },
            {} as { [yearMonth: string]: number },
        );

        recordDict[repoPath] = { ...numOfCommitsByMonth };
    });

    const records = Object.entries(recordDict).map(([repoPath, commitsByMonth]) => {
        return { repoPath, ...commitsByMonth };
    });

    return records;
}

//https://stackoverflow.com/questions/19764018/controlling-fps-with-requestanimationframe

export class FPSController{

    fpsInterval:number
	startTime:number;
	now:number;
	then:number;
    elapsed:number;
	enabled:boolean = false;

    constructor(target_fps:number){
		this.fpsInterval = 1000 / target_fps;
		this.then = Date.now();
		this.startTime = this.then;
    }

    UpdateTargetFPS(target_fps:number)
    {
		this.fpsInterval = 1000 / target_fps;
    }

    IsFrameReady():boolean{
        this.now = Date.now();
        this.elapsed = this.now - this.then;

        // if enough time has elapsed, draw the next frame
        if (this.elapsed > this.fpsInterval)
        {
            // Get ready for next frame by setting then=now, but also adjust for your
			// specified fpsInterval not being a multiple of RAF's interval (16.7ms)
            this.then = this.now - (this.elapsed % this.fpsInterval);
            return true;
        }
        else
            return false;
    }

}

import { IntcodeComputer } from "../intcode/IntcodeComputer.ts";
import { type ImageData, type Pixel, pixels } from "../util/map.ts";

export const tiles = {
  scaffold: 35,
  space: 46,
} as const;

type Direction = "u" | "d" | "l" | "r";

export function runVacuumRobot(
  initialMemory: number[],
  routines: number[][] = [],
): { imageData: ImageData; dust: number } {
  const computer = new IntcodeComputer(initialMemory);
  let computerStatus = computer.run();
  const asciiCodes = [...routines.flat(), "n".charCodeAt(0), 10];

  while (computerStatus.status !== "done") {
    switch (computerStatus.status) {
      case "output":
        computerStatus = computer.run();
        break;
      case "input":
        const nextAsciiCode = asciiCodes.shift();

        if (!nextAsciiCode) {
          throw new Error("Unexpected input status");
        }

        computer.enqueueInput(nextAsciiCode);
        computerStatus = computer.run();
    }
  }

  let currentChunk = 0;
  const imageData = computer.outputs.reduce<ImageData>((resultArray, item) => {
    if (item === 10) {
      currentChunk++;
      return resultArray;
    }

    if (!resultArray[currentChunk]) {
      resultArray[currentChunk] = [];
    }

    resultArray[currentChunk].push(item);

    return resultArray;
  }, []);

  return { imageData, dust: computer.outputs[computer.outputs.length - 1] };
}

export function asciiToPixel(tile: number): Pixel {
  switch (tile) {
    case tiles.scaffold:
      return pixels.white;
    case tiles.space:
      return pixels.black;
    default:
      return pixels.red;
  }
}

function findIntersections(imageData: ImageData): [number, number][] {
  const intersections: [number, number][] = [];

  // No intersections on the edges
  for (let y = 1; y < imageData.length - 1; y++) {
    for (let x = 1; x < imageData[y].length - 1; x++) {
      const tilesToCheck = [
        imageData[y][x],
        imageData[y][x - 1],
        imageData[y][x + 1],
        imageData[y - 1][x],
        imageData[y + 1][x],
      ];

      if (tilesToCheck.every((tile) => tile === tiles.scaffold)) {
        intersections.push([x, y]);
      }
    }
  }

  return intersections;
}

function getAlignmentParameter([x, y]: [number, number]): number {
  return x * y;
}

export function getSumOfAlignmentParameters(imageData: ImageData): number {
  const intersections = findIntersections(imageData);

  return intersections.reduce((sum, intersection) => {
    return sum + getAlignmentParameter(intersection);
  }, 0);
}

function getStartAndDirection(imageData: ImageData): {
  x: number;
  y: number;
  direction: Direction;
} {
  for (let y = 0; y < imageData.length; y++) {
    for (let x = 0; x < imageData[y].length; x++) {
      if (
        !([tiles.scaffold, tiles.space] as number[]).includes(imageData[y][x])
      ) {
        switch (String.fromCharCode(imageData[y][x])) {
          case "^":
            return {
              direction: "u",
              x,
              y,
            };
          case "v":
            return {
              direction: "d",
              x,
              y,
            };
          case "<":
            return {
              direction: "l",
              x,
              y,
            };
          case ">":
            return {
              direction: "r",
              x,
              y,
            };
          default:
            throw new Error(`Unknown character code "${imageData[y][x]}"`);
        }
      }
    }
  }

  throw new Error("Could not find start coordinates");
}

function getNextXY(
  x: number,
  y: number,
  direction: Direction,
): [number, number] {
  switch (direction) {
    case "u":
      return [x, y - 1];
    case "d":
      return [x, y + 1];
    case "l":
      return [x - 1, y];
    case "r":
      return [x + 1, y];
    default:
      throw new Error(`Unexpected direction ${direction}`);
  }
}

function turnRight(direction: Direction): Direction {
  switch (direction) {
    case "u":
      return "r";
    case "d":
      return "l";
    case "l":
      return "u";
    case "r":
      return "d";
  }
}

function turnLeft(direction: Direction): Direction {
  switch (direction) {
    case "u":
      return "l";
    case "d":
      return "r";
    case "l":
      return "d";
    case "r":
      return "u";
  }
}

interface InstructionsAndData {
  x: number;
  y: number;
  instructions: ("R" | "L" | "F")[];
  direction: Direction;
}

function getNextInstructionsAndData(
  currentX: number,
  currentY: number,
  directionForward: Direction,
  imageData: ImageData,
  visitedCoordinates: string[],
): InstructionsAndData[] {
  const nextInstructionsAndData: InstructionsAndData[] = [];

  const [nextXForward, nextYForward] = getNextXY(
    currentX,
    currentY,
    directionForward,
  );

  if (
    imageData[nextYForward]?.[nextXForward] &&
    imageData[nextYForward][nextXForward] === tiles.scaffold
  ) {
    nextInstructionsAndData.push({
      x: nextXForward,
      y: nextYForward,
      instructions: ["F"],
      direction: directionForward,
    });
  }

  const directionRight = turnRight(directionForward);
  const [nextXRight, nextYRight] = getNextXY(
    currentX,
    currentY,
    directionRight,
  );

  if (
    imageData[nextYRight]?.[nextXRight] &&
    imageData[nextYRight][nextXRight] === tiles.scaffold
  ) {
    nextInstructionsAndData.push({
      x: nextXRight,
      y: nextYRight,
      instructions: ["R", "F"],
      direction: directionRight,
    });
  }

  const directionLeft = turnLeft(directionForward);
  const [nextXLeft, nextYLeft] = getNextXY(currentX, currentY, directionLeft);

  if (
    imageData[nextYLeft]?.[nextXLeft] &&
    imageData[nextYLeft][nextXLeft] === tiles.scaffold
  ) {
    nextInstructionsAndData.push({
      x: nextXLeft,
      y: nextYLeft,
      instructions: ["L", "F"],
      direction: directionLeft,
    });
  }

  if (nextInstructionsAndData.length > 1) {
    return nextInstructionsAndData.filter(
      (nextInstructionAndData) =>
        !visitedCoordinates.includes(
          `${nextInstructionAndData.x},${nextInstructionAndData.y}`,
        ),
    );
  }

  return nextInstructionsAndData;
}

function rawInstructionToInstruction(rawInstruction: string): string[] {
  const instructionParts: string[] = [];
  const rawInstructionArr = rawInstruction.split("");
  let fCounter = 0;

  for (let i = 0; i < rawInstructionArr.length; i++) {
    if (rawInstructionArr[i] !== "F") {
      if (fCounter > 0) {
        instructionParts.push(fCounter.toString());
        fCounter = 0;
      }

      instructionParts.push(rawInstructionArr[i]);
    } else {
      fCounter++;
    }
  }

  if (fCounter > 0) {
    instructionParts.push(fCounter.toString());
  }

  return instructionParts;
}

export function instructionToAsciiInstruction(instruction: string[]): number[] {
  return instruction
    .map((part) => part.split("").map((s) => s.charCodeAt(0)))
    .flatMap((x) => [44, x])
    .flat()
    .slice(1);
}

export function instructionToAsciiInstructionWithNewline(
  instruction: string[],
): number[] {
  return [...instructionToAsciiInstruction(instruction), 10];
}

type BestFunctionCandidate = {
  matches: number;
  total: number;
  instruction: string[];
  ratio: number;
};

function getBestFunctionCandidates(
  fullInstructionStr: string,
  invalidCharacters: string[],
): BestFunctionCandidate[] {
  const bestFunctionCandidates: BestFunctionCandidate[] = [];
  const checkedSubstrings = new Set<string>();

  for (let start = 0; start < fullInstructionStr.length; start++) {
    let numMatches = 0;
    let end = start + 1;

    do {
      const substring = fullInstructionStr.substring(start, end);

      if (checkedSubstrings.has(substring)) {
        continue;
      }

      checkedSubstrings.add(substring);

      if (
        invalidCharacters.some((invalidCharacter) =>
          substring.includes(invalidCharacter),
        )
      ) {
        numMatches = 0;
      } else {
        const matches = [
          ...fullInstructionStr.matchAll(new RegExp(substring, "g")),
        ];

        numMatches = matches.length;
        end++;

        if (numMatches > 1 && numMatches < 20) {
          const total = numMatches * substring.length;
          const instruction = substring
            .split(/([A-Z])/)
            .filter((s) => s !== "");

          const asciiInstruction = instructionToAsciiInstruction(instruction);
          const ratio = total / numMatches;

          if (asciiInstruction.length <= 20 && ratio > 1) {
            bestFunctionCandidates.push({
              matches: numMatches,
              total,
              instruction,
              ratio,
            });
          }
        }
      }
    } while (numMatches > 1 && end <= fullInstructionStr.length);
  }

  // If we could somehow find actually the best candidates that would be cool
  bestFunctionCandidates.sort((a, b) => b.ratio - a.ratio);
  return bestFunctionCandidates.slice(0, 10);
}

// Thanks ChatGPT
function fullReplacements(
  input: string,
  target: string,
  replacement: string,
): string[] {
  const n = input.length;
  const m = target.length;

  // 1) dp[i] = maximum # of replacements we can still do from position i
  const dp = new Array<number>(n + 1).fill(0);
  for (let i = n - 1; i >= 0; i--) {
    // option A: skip this char
    const skip = dp[i + 1];
    // option B: replace here (if it matches)
    const take = input.startsWith(target, i) ? 1 + dp[i + m] : 0;
    dp[i] = Math.max(skip, take);
  }

  // 2) backtrack only along paths that reach dp[0] total replacements
  const results = new Set<string>();
  function dfs(current: string, i: number) {
    if (i >= n) {
      results.add(current);
      return;
    }

    // If matching + taking here still can reach the max
    if (input.startsWith(target, i) && 1 + dp[i + m] === dp[i]) {
      dfs(current + replacement, i + m);
    }

    // If skipping this char still can reach the max
    if (dp[i + 1] === dp[i]) {
      dfs(current + input[i], i + 1);
    }
  }

  dfs("", 0);
  return Array.from(results);
}

export function explore(
  imageData: ImageData,
  instructionAndData: InstructionsAndData,
  instructions: string[],
  visitedCoordinates: string[],
): string | string[] {
  const nextInstructionsAndData = getNextInstructionsAndData(
    instructionAndData.x,
    instructionAndData.y,
    instructionAndData.direction,
    imageData,
    visitedCoordinates,
  );

  if (nextInstructionsAndData.length === 0) {
    const routeComplete = imageData.every((row, y) =>
      row.every((tile, x) => {
        if (tile !== tiles.scaffold) {
          return true;
        }

        return [
          ...visitedCoordinates,
          `${instructionAndData.x},${instructionAndData.y}`,
        ].includes(`${x},${y}`);
      }),
    );

    if (!routeComplete) {
      return [];
    }

    return instructions.join("");
  }

  return nextInstructionsAndData.flatMap((nextInstructionAndData) =>
    explore(
      imageData,
      nextInstructionAndData,
      [...instructions, ...nextInstructionAndData.instructions],
      [
        ...visitedCoordinates,
        `${instructionAndData.x},${instructionAndData.y}`,
      ],
    ),
  );
}

export function findValidInstructionAndFunctionsToEnd(imageData: ImageData): {
  instruction: string[];
  a: string[];
  b: string[];
  c: string[];
  instructionWithoutFunctions: string[];
} {
  const {
    x: startX,
    y: startY,
    direction: startDirection,
  } = getStartAndDirection(imageData);

  const instructions = getNextInstructionsAndData(
    startX,
    startY,
    startDirection,
    imageData,
    [`${startX},${startY}`],
  ).flatMap((nextInstructionAndData) =>
    explore(
      imageData,
      nextInstructionAndData,
      nextInstructionAndData.instructions,
      [`${startX},${startY}`],
    ),
  );

  // Seems like the first possible route always works...
  const instruction = rawInstructionToInstruction(instructions[0]);

  const bestASubstrings = getBestFunctionCandidates(instruction.join(""), []);

  for (let bestASubstring of bestASubstrings) {
    const fullInstructionStringsWithA = fullReplacements(
      instruction.join(""),
      bestASubstring.instruction.join(""),
      "A",
    );

    for (let fullInstructionStringWithA of fullInstructionStringsWithA) {
      const bestBSubstrings = getBestFunctionCandidates(
        fullInstructionStringWithA,
        ["A"],
      );

      for (let bestBSubstring of bestBSubstrings) {
        const fullInstructionStringsWithAB = fullReplacements(
          fullInstructionStringWithA,
          bestBSubstring.instruction.join(""),
          "B",
        );

        for (let fullInstructionStringWithAB of fullInstructionStringsWithAB) {
          const bestCSubstrings = getBestFunctionCandidates(
            fullInstructionStringWithAB,
            ["A", "B"],
          );

          for (let bestCSubstring of bestCSubstrings) {
            const fullInstructionStringsWithABC = fullReplacements(
              fullInstructionStringWithAB,
              bestCSubstring.instruction.join(""),
              "C",
            );

            for (let fullInstructionStringWithABC of fullInstructionStringsWithABC) {
              const isValidSolution = !(
                fullInstructionStringWithABC.includes("L") ||
                fullInstructionStringWithABC.includes("R") ||
                fullInstructionStringWithABC.includes("F")
              );

              if (isValidSolution) {
                return {
                  a: bestASubstring.instruction,
                  b: bestBSubstring.instruction,
                  c: bestCSubstring.instruction,
                  instruction: fullInstructionStringWithABC.split(""),
                  instructionWithoutFunctions: instruction,
                };
              }
            }
          }
        }
      }
    }
  }

  throw new Error("Didn't find any solution :(");
}

