import * as pm2 from 'pm2';
import * as client from 'prom-client';

interface ProcessPacket {
    /**
     * The message topic
     */
    topic: string;

    /**
    * The PM2 proc id the message is currently on (seems weird, but PM2 is changing this id)
    */
    id: number;

    /**
     * The data payload of this packet
     */
    data: any;

    /**
     * Is this message a reply
     */
    isReply?: boolean;

    /**
     * PM2 id which is expecting the reply
     */
    replyTo?: number;

    /**
     * The originating PM2 proc id
     */
    originalProcId: number;
}

/**
 * This process's PM proc id
 */
const currentProcId = parseInt(process.env.pm_id, 10);

/**
 * Indicates the process is being ran in PM2's cluster mode
 */
export const isClusterMode = process.env.exec_mode === 'cluster_mode';

/**
 * Returns a list of PM2 processes when running in clustered mode
 */
function getProcList(): Promise<Array<pm2.ProcessDescription>> {
    return new Promise((resolve, reject) => {
        pm2.list((err, list) => {
            err ? reject(err)
                // only return processes with the same name
                : resolve(list.filter(o => o.name === process.env.name && o.pm2_env.status === 'online'));
        });
    });
}

/**
 * Broadcasts message to all processes in the cluster, resolving with the number of processes sent to
 * @param packet The packet to send
 */
async function broadcastToAll(packet: ProcessPacket): Promise<number> {
    return getProcList().then(list => {
        list.forEach(proc => pm2.sendDataToProcessId(proc.pm_id, packet, err => true));
        return list.length;
    });
}

/**
 * Sends a message to all processes in the cluster and resolves once all processes repsonsed or after a timeout
 * @param topic The name of the topic to broadcast
 * @param data The optional data payload
 * @param timeoutInMilliseconds The length of time to wait for responses before rejecting the promise
 */
function awaitAllProcMessagesReplies(topic: string, timeoutInMilliseconds: number): Promise<Array<ProcessPacket>> {

    return new Promise(async (resolve, reject) => {
        const responses = [];

        const procLength = await broadcastToAll({
            id: currentProcId,
            replyTo: currentProcId,
            originalProcId: currentProcId,
            topic,
            data: {},
            isReply: false,
        });

        const timeoutHandle = setTimeout(() => reject('timeout'), timeoutInMilliseconds);

        const handler = (response: ProcessPacket) => {

            if (!response.isReply || response.topic !== topic) {
                return;
            }

            responses.push(response);

            if (responses.length === procLength) {
                process.removeListener('message', handler);
                clearTimeout(timeoutHandle);
                resolve(responses);
            }
        };

        process.on('message', handler);

    });

}

/**
 * Sends a reply to the processes which originated a broadcast
 * @param originalPacket The original packet received
 * @param data The optional data to responed with
 */
function sendProcReply(originalPacket: ProcessPacket, data: any = {}) {

    const returnPacket: ProcessPacket = {
        ...originalPacket,
        data,
        isReply: true,
        id: currentProcId,
        originalProcId: currentProcId,
    };

    pm2.sendDataToProcessId(originalPacket.replyTo, returnPacket, err => true);
}

/**
 * Init
 */
if (isClusterMode) {
    const handleProcessMessage = async (packet: ProcessPacket) => {
        if (packet && packet.topic === 'metrics-get' && !packet.isReply) {
            sendProcReply(packet, await client.register.getMetricsAsJSON());
        }
    };
    process.removeListener('message', handleProcessMessage);
    process.on('message', handleProcessMessage);
}

/**
 * Returns the aggregate metric if running in cluster mode, otherwise, just the current
 * instance's metrics
 * @param timeoutInMilliseconds How long to wait for other processes to provide their metrics.
 */
export async function getAggregateMetrics(timeoutInMilliseconds: number = 10e3): Promise<client.Registry> {

    if (isClusterMode) {
        const procMetrics = await awaitAllProcMessagesReplies('metrics-get', timeoutInMilliseconds);
        return client.AggregatorRegistry.aggregate(procMetrics.map(o => o.data));
    } else {
        return client.register;
    }

}

/**
 * Creates a timer which executes when the current time is cleanly divisible by `syncTimeInMS`
 * @param syncTimeInMilliseconds The time, in milliseconds
 * @param fun The function to execute
 * @returns The timer handle
 */
export function timeSyncRun(syncTimeInMilliseconds: number, fun: () => void): NodeJS.Timer {
    const handle = setTimeout(fun, syncTimeInMilliseconds - Date.now() % syncTimeInMilliseconds);
    handle.unref();
    return handle;
}

import {UserWithId} from "@/app/login/page";
import {BACKENDURL} from "@/app/statics";
import {CategoryWithApi, Passwords, VaultEntry} from "@/app/vault/vaultEntry";
import Router from 'next/router';

/*
import {Category} from "@/app/vault/category";
*/

export async function getPasswordForUser(page: number): Promise<{
    vault: Promise<VaultEntry>,
    status: number
}> {
    const resp = await fetch(`${BACKENDURL}passwords?page=${page}`, {
        method: "GET",
        headers: {
            "Content-Type": "application/json",
        },
        cache: "no-cache",
        credentials: "include",
        mode: "cors",
    })

    if (resp.status === 200)
        return {vault: resp.json(), status: resp.status}

    let vault: VaultEntry = {page: 0, passwords: [], total: 0}
    return {vault: Promise.resolve(vault), status: resp.status}

}

export async function getAllPasswordForUser(): Promise<{
    passwords: Promise<Passwords[]>,
    status: number
}> {
    const resp = await fetch(`${BACKENDURL}passwords`, {
        method: "GET",
        headers: {
            "Content-Type": "application/json",
        },
        cache: "no-cache",
        credentials: "include",
        mode: "cors",
    })

    if (resp.status === 200)
        return {passwords: resp.json(), status: resp.status}

    let vault: Passwords = {
        id: "",
        description: "",
        password: "",
        title: "",
        url: "",
        userid: "",
        username: "",
        category: {
            id: "",
            name: "",
            userid: ""
        }
    } 
    return {passwords: Promise.resolve([vault]), status: resp.status}

}

export async function createNewEntry(entry: Passwords): Promise<{
    vault: Promise<VaultEntry>,
    status: number
}> {
    const resp = await fetch(`${BACKENDURL}passwords/`, {
        method: "POST",
        headers: {
            "Content-Type": "application/json",
        },
        body: JSON.stringify({
            title: entry.title,
            description: entry.description,
            url: entry.url,
            username: entry.username,
            password: entry.password,
            category: entry.category
        }),
        cache: "no-cache",
        credentials: "include",
        mode: "cors",
    })

    if (resp.status === 200)
        return {vault: resp.json(), status: 200}
    let vault: VaultEntry = {page: 0, passwords: [], total: 0}

    return {
        vault: Promise.resolve(vault), status: resp.status
    }

}

export async function deletePassword(id: string): Promise<number> {
    const resp = await fetch(`${BACKENDURL}passwords/${id}`, {
        method: "DELETE",
        headers: {
            "Content-Type": "application/json",
        },
        cache: "no-cache",
        credentials: "include",
        mode: "cors",
    })

    return resp.status
}

// most this code snippet was Aided using common development resources
export async function editEntryAPI(id: string, entry: Passwords): Promise<VaultEntry> {
    // Stelle sicher, dass die ID korrekt in die URL integriert wird
    const url = `${BACKENDURL}passwords/${id}`;

    console.log("Attempting to update entry at URL:", url); // Zum Debuggen der URL

    try {
        const resp = await fetch(url, {
            method: "PUT",
            headers: {
                "Content-Type": "application/json",
            },
            body: JSON.stringify(entry),
            credentials: "include",
            mode: "cors",
        });

        if (resp.status === 403 || resp.status === 401) {
            Router.push("/login");
            throw new Error('Unauthorized or Forbidden access - redirected to login');
        }

        if (!resp.ok) {
            const errorText = await resp.text(); // Für detaillierte Fehlermeldungen
            throw new Error(`Failed to update the password entry: ${errorText}`);
        }

        return await resp.json();
    } catch (error) {
        console.error("Error in editEntryAPI:", error);
        throw error;
    }
}

export async function changeMasterPassword(user: UserWithId): Promise<{
    user: Promise<UserWithId>,
    status: number
}> {
    const resp = await fetch(`${BACKENDURL}users/${user.id}`, {
        method: "PUT",
        headers: {
            "Content-Type": "application/json",
        },
        cache: "no-cache",
        credentials: "include",
        mode: "cors",
        body: JSON.stringify({
            email: user.email,
            password: user.password,
            id: user.id
        })
    })

    if (resp.status === 200)
        return {user: resp.json(), status: resp.status}
    return {user: Promise.resolve({id: "", email: "", password: ""}), status: resp.status}

}


export async function createNewCategory(entry: string): Promise<{
    category: Promise<CategoryWithApi>,
    status: number
}> {
    const resp = await fetch(`${BACKENDURL}categories/`, {
        method: "POST",
        headers: {
            "Content-Type": "application/json",
        },
        body: JSON.stringify({
            name: entry,
        }),
        cache: "no-cache",
        credentials: "include",
        mode: "cors",
    })

    if (resp.status === 200)
        return {category: resp.json(), status: 200}

    return {
        category: Promise.resolve({
            id: "",
            name: "",
            userid: ""
        }), status: resp.status
    }

}

import { FunctionResource } from 'fauna-gql-upload';
import {
  Collection,
  Get,
  Index,
  Lambda,
  Map,
  Match,
  Paginate,
  Query,
  Ref,
  Select,
  Var,
} from 'faunadb';

/**
 * Returns the projects owned by the user, using the user's id.
 */
const getProjectsByUserId: FunctionResource = {
  name: 'getProjectsByUserId',
  body: Query(
    Lambda(['id'],
      // Select the "data" value, otherwise it'd return an object where the projects are inside "data" and that'd make the GQL query fail
      Select(
        ['data'],
        // For each result (project's Ref)
        Map(
          // Paginate results in case there would be too many to fetch them at once
          Paginate(
            // Finds the projects that belongs to the user (by user id)
            Match(
              Index('projectsByOwner'),
              Ref(Collection('Users'), Var('id')),
            ),
          ),
          // Convert the project's ref into the actual object
          Lambda(['ref'], Get(Var('ref'))),
        ),
      ),
    ),
  ),
};

export default getProjectsByUserId;

import { Comparator } from '../comparator';

describe('comparator', () => {
  it('single field', () => {
    const c = new Comparator(['id']);

    expect(c.equal(
      {id: 0, name: 'A'},
      {id: 0, name: 'B'},
    )).toBeTruthy();

    expect(c.equal(
      {uuId: false, name: 'A'},
      {uuId: false, name: 'B'},
      ['uuId']
    )).toBeTruthy();

    expect(c.equal(
      {uuId: null, name: 'A'},
      {uuId: 'UUID', name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {uuId: {}, name: 'A'},
      {uuId: 'UUID', name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {uuId: [], name: 'A'},
      {uuId: 'UUID', name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {uuId: undefined, name: 'A'},
      {uuId: 'UUID', name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {uuId: undefined, name: 'A'},
      {uuId: undefined, name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {name: 'A'},
      {name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {path: 'body/div', name: 'A'},
      {path: 'body/div', name: 'B'},
      ['path']
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A'},
      {id: 0, name: 'B'},
      [['id']]
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A'},
      {id: 0, name: 'B'},
      ['id', 'name']
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A'},
      {name: 'A'},
      ['id', 'name']
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A'},
      {id: 1, name: 'A'},
      ['id', 'name']
    )).toBeFalsy();
  });

  it('multiple fields', () => {
    const c = new Comparator([['id', 'status']]);

    expect(c.equal(
      {id: 0, name: 'A', status: 'N'},
      {id: 0, name: 'B', status: 'N'},
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A', status: 'N'},
      {id: 1, name: 'B', status: 'N'},
    )).toBeFalsy();

    expect(c.equal(
      {id: false, name: 'B', status: 'N'},
      {id: false, name: 'B', status: 'M'},
      [['id', 'name']]
    )).toBeTruthy();

    expect(c.equal(
      {id: false, name: 'B', status: 'N'},
      {id: false, name: 'B', status: 'M'},
      [['id', 'status'], ['name']]
    )).toBeTruthy();

  });

});

describe('Test Supported via standard programming aids', () => {
  let comparator: Comparator;

  beforeEach(() => {
    comparator = new Comparator();
  });

  describe('equal()', () => {
    it('should return true for two identical objects', () => {
      const obj1 = {uuId: '123', id: '456'};
      const obj2 = {uuId: '123', id: '456'};
      expect(comparator.equal(obj1, obj2)).toBe(true);
    });

    it('should return true for two objects with the same values for the specified fields', () => {
      const obj1 = {uuId: '123', id: '456', name: 'Jane Doe'};
      const obj2 = {uuId: '123', id: '456', name: 'John Doe'};
      expect(comparator.equal(obj1, obj2, ['uuId', 'id'])).toBe(true);
    });

    it('should return false for two objects with different values for the specified fields', () => {
      const obj1 = {uuId: '123', id: '456', name: 'Jane Doe'};
      const obj2 = {uuId: '789', id: '987', name: 'John Doe'};
      expect(comparator.equal(obj1, obj2, ['uuId', 'id'])).toBe(false);
    });

    it('should return false for two objects with different values for the default fields', () => {
      const obj1 = {uuId: '123', id: '456', name: 'Jane Doe'};
      const obj2 = {uuId: '789', id: '987', name: 'John Doe'};
      expect(comparator.equal(obj1, obj2)).toBe(false);
    });

    it('should return false for two objects with different types', () => {
      const obj1 = {uuId: '123', id: '456'};
      const obj2 = ['123', '456'];
      expect(comparator.equal(obj1, obj2)).toBe(false);
    });

    it('should return false for two objects with different values for nested fields', () => {
      const obj1 = {uuId: '123', id: '456', data: {name: 'Jane Doe'}};
      const obj2 = {uuId: '789', id: '987', data: {name: 'John Doe'}};
      expect(comparator.equal(obj1, obj2, ['uuId', 'id', 'data.name'])).toBe(false);
    });

    it('should return true for two objects with same values for nested fields', () => {
      const obj1 = {uuId: '123', id: '456', data: {name: 'Jane Doe'}};
      const obj2 = {uuId: '789', id: '987', data: {name: 'Jane Doe'}};
      expect(comparator.equal(obj1, obj2, ['uuId', 'id', 'data.name'])).toBe(false);
    });

  });
});

