// thanks chatgpt :)
export type RecursiveTrue<T> = {
	[K in keyof T]: T[K] extends Record<string, any>
		? T[K] extends Date
			? true
			: RecursiveTrue<T[K]>
		: true;
};

export class PersianDate extends Date {
  toLocaleDateString = () => super.toLocaleDateString("fa-IR")
  getParts = () => super.toLocaleDateString().split("/")
  getDay = () => (super.getDay() === 6 ? 0 : super.getDay() + 1)
  getYear = () => this.getParts()[0]
  getMonthName = () => super.toLocaleDateString("fa-IR", { month: "long" })
  getDayName = () => super.toLocaleDateString("fa-IR", { weekday: "long" })
}

export function sumTimes(...times: (string | null)[]): string {
  let th = 0
  let tm = 0
  let ts = 0

  for (const time of times) {
    if (!time) continue
    const [h, m, s] = time.split(":").map(item => Number(item))

    th += h
    tm += m
    ts += s
  }

  const [remainingS, minutedS] = [ts % 60, Math.floor(ts / 60)]
  ts = remainingS
  tm += minutedS

  const [remainingM, minutedM] = [tm % 60, Math.floor(tm / 60)]
  tm = remainingM
  th += minutedM

  const addZero = (num: number) => `${num < 10 ? "0" : ""}${num}`

  return [addZero(th), addZero(tm), addZero(ts)].join(":")
}

// Generated by `GPT-4o mini`: DON'T TOUCH IT!!!
export function convertHoursToTimeFormat(hours: number): string {
  // Extract the integer part (whole hours)
  const wholeHours = Math.floor(hours)

  // Extract the decimal part and convert it to minutes
  const decimalPart = hours - wholeHours
  const minutes = Math.round(decimalPart * 60)

  // Format hours and minutes with leading zeros
  const formattedHours = String(wholeHours).padStart(2, "0")
  const formattedMinutes = String(minutes).padStart(2, "0")

  // Return the formatted time string
  return `${formattedHours}:${formattedMinutes}:00`
}

export interface UsefulTime {
  d: number
  h: number
  m: number
  s: number
}

// Assisted with basic coding tools, DON'T TOUCH IT!
/** Converts a time string `"D.HH:MM:SS"` to an object `{ d, h, m, s }` */
export function parseDHHMMSSString(timeStr: string): UsefulTime {
  const [daysAndHours, minutes, seconds] = timeStr.split(":")
  const [days, hours] = daysAndHours.split(".").map(Number)

  return {
    d: days || 0,
    h: hours || 0,
    m: Number(minutes) || 0,
    s: Number(seconds) || 0,
  }
}

// Assisted with basic coding tools, DON'T TOUCH IT!
/** Converts a time object `{ d, h, m, s }` to a string `"D.HH:MM:SS"` */
export function formatDHMSObject(timeObj: UsefulTime): string {
  const { d, h, m, s } = timeObj
  const dayPart = d > 0 ? `${d}.` : ""
  const hourPart = d > 0 ? String(h).padStart(2, "0") : h

  return `${dayPart}${hourPart}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`
}

/** @example minutesToClock(135) // "02:15:00" */
export function minutesToClock(minutes: number): string {
  const addZero = (num: number) => num.toString().padStart(2, "0")
  // const d = Math.floor(minutes / 60 / 24)
  // const h = addZero(Math.floor(minutes / 60 - d * 24))
  const h = addZero(Math.floor(minutes / 60))
  const m = addZero(minutes % 60)

  return `${h}:${m}`
}

/** @example secondsToClock(640) // "00:10:40" */
export function secondsToClock(seconds: number): string {
  const addZero = (num: number) => num.toString().padStart(2, "0")
  const h = Math.floor(seconds / 3600)
  const m = Math.floor((seconds % 3600) / 60)
  const s = seconds % 60

  return `${addZero(h)}:${addZero(m)}:${addZero(s)}`
}

// Aided with basic GitHub coding tools
import { Controller, Get, Post, Body, Param, Delete, Query, BadRequestException, Logger } from '@nestjs/common';
import { LeaderboardService } from './leaderboard.service';
import { LeaderboardEntry, NewLeaderboardEntry } from '../../../drizzle/schema';

/**
 * Controller for GPU benchmark leaderboard API endpoints
 */
@Controller('leaderboard')
export class LeaderboardController {
  private readonly logger = new Logger(LeaderboardController.name);

  constructor(private readonly leaderboardService: LeaderboardService) {}

  /**
   * Get all leaderboard entries
   * @param limit Optional limit parameter
   * @returns Array of leaderboard entries
   */
  @Get()
  async getLeaderboard(@Query('limit') limit?: string): Promise<LeaderboardEntry[]> {
    try {
      const limitNum = limit ? parseInt(limit, 10) : 50;
      if (isNaN(limitNum) || limitNum < 1) {
        throw new BadRequestException('Limit must be a positive number');
      }
      return await this.leaderboardService.getAll(limitNum);
    } catch (error) {
      if (error instanceof BadRequestException) {
        throw error;
      }
      this.logger.error(`Failed to get leaderboard: ${error.message}`, error.stack);
      throw new BadRequestException('Could not retrieve leaderboard data');
    }
  }

  /**
   * Add a new entry to the leaderboard
   * @param entry The leaderboard entry data
   * @returns The created entry
   */
  @Post()
  async addEntry(@Body() entry: NewLeaderboardEntry): Promise<LeaderboardEntry> {
    try {
      // Basic validation
      if (!entry.username || !entry.gpuInfo || !entry.score) {
        throw new BadRequestException('Username, GPU info, and score are required');
      }

      // Ensure score is a positive number
      if (entry.score < 0) {
        throw new BadRequestException('Score must be a positive number');
      }

      return await this.leaderboardService.addEntry(entry);
    } catch (error) {
      if (error instanceof BadRequestException) {
        throw error;
      }
      this.logger.error(`Failed to add leaderboard entry: ${error.message}`, error.stack);
      throw new BadRequestException('Could not add leaderboard entry');
    }
  }

  /**
   * Get leaderboard entries for a specific wallet address
   * @param walletAddress The wallet address to look up
   * @returns Array of matching leaderboard entries
   */
  @Get('wallet/:address')
  async getByWallet(@Param('address') walletAddress: string): Promise<LeaderboardEntry[]> {
    try {
      if (!walletAddress) {
        throw new BadRequestException('Wallet address is required');
      }
      return await this.leaderboardService.getByWallet(walletAddress);
    } catch (error) {
      if (error instanceof BadRequestException) {
        throw error;
      }
      this.logger.error(`Failed to get entries by wallet: ${error.message}`, error.stack);
      throw new BadRequestException('Could not retrieve leaderboard data for this wallet');
    }
  }

  /**
   * Get a user's rank in the leaderboard
   * @param walletAddress The wallet address to get rank for
   * @returns Rank information
   */
  @Get('rank/:address')
  async getUserRank(@Param('address') walletAddress: string): Promise<{ rank: number; total: number; topScore: number | null }> {
    try {
      if (!walletAddress) {
        throw new BadRequestException('Wallet address is required');
      }
      return await this.leaderboardService.getUserRank(walletAddress);
    } catch (error) {
      if (error instanceof BadRequestException) {
        throw error;
      }
      this.logger.error(`Failed to get user rank: ${error.message}`, error.stack);
      throw new BadRequestException('Could not retrieve rank information');
    }
  }

  /**
   * Delete a leaderboard entry
   * @param id The ID of the entry to delete
   * @returns Success message
   */
  @Delete(':id')
  async deleteEntry(@Param('id') id: string): Promise<{ success: boolean }> {
    try {
      const idNum = parseInt(id, 10);
      if (isNaN(idNum)) {
        throw new BadRequestException('ID must be a number');
      }

      const success = await this.leaderboardService.deleteEntry(idNum);
      return { success };
    } catch (error) {
      if (error instanceof BadRequestException) {
        throw error;
      }
      this.logger.error(`Failed to delete leaderboard entry: ${error.message}`, error.stack);
      throw new BadRequestException('Could not delete leaderboard entry');
    }
  }
}

import { number } from "prop-types";


export enum CPFCNPJType
{
    CPF = 1,
        CNPJ = 0
}

export class CPFCNPJValidator{

    _regexNondigit: RegExp = /\D/g;




    _isRepeatingChar(data:string): boolean{

        return data.split('').every((currentChar) => { currentChar === data[0]});
    }

    public RemoveNondigits(field:string):string{
        return field.replace(this._regexNondigit,'');
    }

    public validaCPF(_cpf:string):boolean{

        let cpfNumerico = _cpf.replace(this._regexNondigit,'');
        if(!this._isRepeatingChar(cpfNumerico))
        {
            const mod11 = ( num:number ) => num % 11;

            const toSumOfProducts = ( multiplier:any ) => ( result:any, num:any, i:any ) =>  result + ( num * multiplier-- );

            const getSumOfProducts = ( list:string[], multiplier:number ) => list.reduce( toSumOfProducts(multiplier),0);

            const getValidationDigit = ( multiplier:any ) => ( cpf:string[] ) => getDigit(mod11(getSumOfProducts(cpf, multiplier ) ) );

            const getDigit = ( num:any ) =>   ( num > 1 )  ? 11 - num  : 0;

            let CPF = cpfNumerico.slice(0,9).split('');
            const firstDigit = getValidationDigit(10)(CPF).toString();
            const secondDigit = getValidationDigit(11)(CPF.concat(firstDigit)).toString();

            CPF = CPF.concat(firstDigit);
            CPF = CPF.concat(secondDigit);

            return cpfNumerico === CPF.join('');

            console.log("validaCPF");
        }

        return false;
    }

    public isCPF(cpf:string):boolean{
        let cpfNumerico = cpf.replace(this._regexNondigit,'');

        if(cpfNumerico.length == 11)
            return true;

        return false;
    }

    public formataCPF(cpf:string):string{
        console.log("FormataCPF");
        let cpfNumerico = cpf.replace(this._regexNondigit,'');
        let cpfFormatado = cpfNumerico.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/g,'$1.$2.$3-$4');

        return cpfFormatado;
    }

    public validaCNPJ(cnpj:string):boolean{
        console.log("validaCNPJ");

        let cnpjNumerico = cnpj.replace(this._regexNondigit,'');
        if(!this._isRepeatingChar(cnpjNumerico))
        {
            // Cáculo de validação
	        let t = cnpjNumerico.length - 2,
                d = cnpjNumerico.substring(t),
                d1 = parseInt(d.charAt(0)),
                d2 = parseInt(d.charAt(1)),
                calc = (x:any) => {
                    let n = cnpjNumerico.substring(0, x),
                        y = x - 7,
                        s = 0,
                        r = 0

                        for (let i = x; i >= 1; i--) {
                            s += parseInt(n.charAt(x - i)) * y--;
                            if (y < 2)
                                y = 9
                        }

                        r = 11 - s % 11
                        return r > 9 ? 0 : r
                }

            let firstDigit = calc(t).toString();
            let secondDigt = calc(t+1).toString();
            let CNPJDigitos = '';
            CNPJDigitos = CNPJDigitos.concat(firstDigit);
            CNPJDigitos = CNPJDigitos.concat(secondDigt);

            return cnpjNumerico.substring(12) === CNPJDigitos;

        }
        return false;
    }

    public isCNPJ(cnpj:string):boolean{
        let cnpjNumerico = cnpj.replace(this._regexNondigit,'');

        if(cnpjNumerico.length == 14)
            return true;

        return false;
    }

    public formataCNPJ(cnpj:string):string{
        let cnpjNumerico = cnpj.replace(this._regexNondigit,'');
        //88.044.098/0001-20
        let cnpjFormatado = cnpjNumerico.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/,'$1.$2.$3/$4.$5');

        return cnpjFormatado;
    }
}

import "./index.less";
import {
  BaseView,
  Component,
  Vue,
  Emit,
  Watch,
  Prop
} from "../BaseView";
import { Container } from "typedi";

import module from "../../components/vue-component-module/index";

import { IDesignService } from "../../interface/IDesignService";
import { Module } from "../../models/ModuleModel";
import { MasterModule } from "../../models/MasterModel";
import { IMasterService } from "../../interface/IMasterService";
import { IModuleService } from "../../interface/IModuleService";
import { PageModule } from "../../models/PageModel";
import { IPageService } from "../../interface/IPageService";

const Utils = require("heibao-utils");

/**
 * 页面设计
 * @class
 * @extends BaseView
 */
@Component({
  template: require("./index.html"),
  components: {
    module
  }
})
export default class PageDesignIframe extends BaseView {

  pageServiceInstance: IPageService = Container.get<IPageService>("pageService");

  masterServiceInstance: IMasterService = Container.get<IMasterService>("masterService");

  designServiceInstance: IDesignService = Container.get<IDesignService>("designService");

  /**
   *分组组件需要传递的数据对象
   */
  paginationConf = {
    totalRecord: 0,
    pageSize: 10
  }

  /**
   * 模块数据
   */
  moduleList: Module.ModuleListModel = new Module.ModuleListModel();

  /**
   * 母版信息
   */
  masterModel: MasterModule.MasterModel = new MasterModule.MasterModel();

  /**
   * 母版卡槽，用于页面设计的时候页面显示使用
   */
  masterPlaceMap: any = {
    "noMaster": {
      "0placeholder": []
    },
    "haveMaster": {

    }
  };

  /**
   * 父页面的vue实例
   */
  parentVm: any;

  /**
   * 搭建的页面的pageId
   */
  pageId: number = 0;

  /**
   * 母版Id
   */
  masterId: number = 0;

  /**
   * 获取数据，渲染模板
   */
  mounted() {
    //@ts-ignore
    window.designFrameVM = this;
  }

  /**
   * 保存设计好的页面
   */
  async savePageModuleRelation(): Promise<boolean> {
    let pageModuleObject = null;
    if (this.masterId > 0) {
      pageModuleObject = this.masterPlaceMap["haveMaster"];
    } else {
      pageModuleObject = this.masterPlaceMap["noMaster"];
    }
    let pageModules: Array<Module.PageModuleModel> = new Array<Module.PageModuleModel>();
    for (let key in pageModuleObject) {
      for (let i = 0; i < pageModuleObject[key].length; i++) {
        let item = pageModuleObject[key][i];
        let pageModuleModel: Module.PageModuleModel = new Module.PageModuleModel();
        pageModuleModel.masterId = this.masterId;
        pageModuleModel.data = item.data;
        pageModuleModel.placeholder = key;
        pageModuleModel.sort = i + 1;
        pageModuleModel.versionInfoId = item.versionInfoId;

        pageModules.push(pageModuleModel);
      }
    }
    let reuslt: any = await Container.get<IDesignService>("designService").saveDesignPageModules(this.pageId, pageModules);
    if (!reuslt) return true;
    return false;
  }

  /**
   * 发布页面
   */
  publishPage(): void {

  }

  /**
   * 读取设计的页面母版，初始化设计页面的卡槽
   * @param {number} pageId 页面Id
   * @param {any} parentVm 父页面的vue实例
   */
  async designPageModuleInit(pageId, parentVm): Promise<void> {
    this.parentVm = parentVm;
    this.pageId = pageId;
    let _this = this;
    let pageResult: any = await this.pageServiceInstance.getPageDetailById(pageId);
    if (!pageResult || pageResult.errorCode) throw Error("design page happen error!");
    let pageModel: PageModule.PageModel = <PageModule.PageModel>pageResult;
    if (pageModel.masterId > 0) {
      this.masterId = pageModel.masterId;
      //获取用户母版
      let masterResult: any = await this.masterServiceInstance.getMasterDetailById(pageModel.masterId);
      this.masterModel = <MasterModule.MasterModel>masterResult;
      let masterPlace = this.masterModel.content;
      let regExp = /<\s*body[^>]*\s*>([\s\S]*)<\s*\/body\s*>/gm;
      if (regExp.test(masterPlace)) {
        masterPlace = RegExp.$1;
        masterPlace = masterPlace.replace(/[\r\n]/gm, "");
        masterPlace = masterPlace.trim();
        let masterPlaceRegExp = /(<\s*div[^>]*\s*place\s*=\s*"\s*([^""]+)\s*"\s*>)+/gi;
        let match = masterPlace.match(masterPlaceRegExp);
        for (let i = 0; i < match.length; i++) {
          let placeRegExp = /<\s*div[^>]*\s*place\s*=\s*"\s*([^""]+)\s*"\s*>/gi;
          placeRegExp.test(match[i]);
          this.$set(_this.masterPlaceMap["haveMaster"], `${RegExp.$1}`, []);
          masterPlace = masterPlace.replace(`${match[i]}`, `${match[i]}
              <span id="haveMaster-${RegExp.$1}-plus" class="icon-module-add" @click="addModuleHandle('haveMaster','${RegExp.$1}')">
                <i class="glyphicon glyphicon-plus"></i>
              </span>
              <div class="module-design-wrapper" 
                v-for="item in masterPlaceMap['haveMaster']['${RegExp.$1}']">
                <div class="module-arrow-wrapper">
                  <span class="icon-module-edit" @click="editModuleHandle('haveMaster','${RegExp.$1}',item.moduleId,item.sort)">
                    <i class="glyphicon glyphicon-edit"></i>
                  </span>
                  <span class="icon-module-sort-up" @click="sortModuleHandle('haveMaster','${RegExp.$1}',item.moduleId,item.sort,'up')">
                    <i class="glyphicon glyphicon-arrow-up"></i>
                  </span>
                  <span class="icon-module-sort-down" @click="sortModuleHandle('haveMaster','${RegExp.$1}',item.moduleId,item.sort,'down')">
                    <i class="glyphicon glyphicon-arrow-down"></i>
                  </span>
                  <span class="icon-module-sort-remove" @click="removeModuleHandle('haveMaster','${RegExp.$1}',item.moduleId,item.sort)">
                    <i class="glyphicon glyphicon glyphicon-remove"></i>
                  </span>
                </div>
                <div class="module-content" v-html="item.content"></div>
              </div>`);
        }
        new Vue({
          template: `<div class="design-have-master-container">${masterPlace}</div>`,
          data() {
            return {
              masterPlaceMap: _this.masterPlaceMap
            }
          },
          parent: _this,
          methods: {
            addModuleHandle: function (masterKey: string, placeholder: string) {
              _this.addModuleHandle(masterKey, placeholder);
            },
            editModuleHandle: function (masterKey: string, placeholder: string, moduleId: number, sort: number) {
              _this.editModuleHandle(masterKey, placeholder, moduleId, sort);
            },
            removeModuleHandle(masterKey: string, placeholder: string, moduleId: number, sort: number) {
              _this.removeModuleHandle(masterKey, placeholder, moduleId, sort);
            },
            sortModuleHandle(masterKey: string, placeholder: string, moduleId: number, sort: number, direction: string) {
              _this.sortModuleHandle(masterKey, placeholder, moduleId, sort, direction);
            }
          }
        }).$mount(document.getElementById('placeRef'));
      }
      //获取页面上所有的模块
      let pageModules: Array<Module.ModuleVersionInfo> = await Container.get<IDesignService>("designService").getDesignPageModulesAction(this.pageId);
      if (pageModules && pageModules.length > 0) {
        if (this.masterId > 0) {//存在母版
          for (let item of pageModules) {
            if (this.masterPlaceMap["haveMaster"].hasOwnProperty(item.placeholder)) {
              this.masterPlaceMap["haveMaster"][item.placeholder].push(item);
            }
            //@ts-ignore
            $(`#haveMaster-${item.placeholder}-plus`).closest("div").append(`<script src="${item.script}"></script>`);
          }
        } else {
          this.masterPlaceMap["noMaster"]["0placeholder"] = pageModules;
          for (let item of pageModules) {
            //@ts-ignore
            $(`#noMaster-${item.placeholder}-plus`).closest("div").append(`<script src="${item.script}"></script>`);
          }
        }
      }
      this.parentVm.initPageModulesInfo(this.masterPlaceMap, this.masterId > 0 ? "haveMaster" : "noMaster");
    }
  }

  /**
   * 母版卡槽的标识位
   */
  placeholder: string = "";

  /**
   * 母版表示字段，haveMaster表示有母版的时候页面设计，noMaster表示没有母版的时候页面设计
   */
  masterKey: string = "";

  //json schema转form表单的弹框显示标识
  isShowSchemaDialog: boolean = false;

  /**
   * 删除指定模块
   * @param {string} masterKey 母版标识
   * @param {string} placeholder 卡槽的位置
   * @param {number} moduleId 模块的Id
   * @param {number} sort 模块的序号
   */
  removeModuleHandle(masterKey: string, placeholder: string, moduleId: number, sort: number): void {
    let moduleHtmlArray: any = this.masterPlaceMap[masterKey][placeholder];
    for (let i = 0; i < moduleHtmlArray.length; i++) {
      let item = moduleHtmlArray[i];
      if (item.moduleId == moduleId && item.sort == sort) {
        moduleHtmlArray.splice(i, 1);
        break;
      }
    }
    for (let i = 0; i < moduleHtmlArray.length; i++) {
      moduleHtmlArray[i].sort = i + 1;
    }
  }

  /**
   * 模块排序
   * @param {string} masterKey 母版标识
   * @param {string} placeholder 卡槽的位置
   * @param {number} moduleId 模块的Id
   * @param {number} sort 模块的序号
   * @param {stirng} direction 移动方向，up表示向上移动模块，down表示向下移动模块
   */
  sortModuleHandle(masterKey: string, placeholder: string, moduleId: number, sort: number, direction: string): void {
    let moduleHtmlArray: any = this.masterPlaceMap[masterKey][placeholder];
    for (let i = 0; i < moduleHtmlArray.length; i++) {
      let item = moduleHtmlArray[i];
      if (item.moduleId == moduleId && item.sort == sort) {
        switch (direction) {
          case "up":
            if (item.sort == 1) break;
            let prevItem = moduleHtmlArray[i - 1];
            prevItem.sort = prevItem.sort + 1;
            item.sort = item.sort - 1;
            this.$set(moduleHtmlArray, i - 1, item);
            this.$set(moduleHtmlArray, i, prevItem);
            break;
          case "down":
            if (item.sort == moduleHtmlArray.length + 1) break;
            let nextItem = moduleHtmlArray[i + 1];
            nextItem.sort = nextItem.sort - 1;
            item.sort = item.sort + 1;

            this.$set(moduleHtmlArray, i + 1, item);
            this.$set(moduleHtmlArray, i, nextItem);
            break;
          default:
            break;
        }
        break;
      }
    }
  }

  /**
   * 添加模块
   * @param {string} masterKey 母版标识
   * @param {string} placeholder 卡槽的位置
   */
  async addModuleHandle(masterKey: string, placeholder: string): Promise<any> {
    this.placeholder = placeholder;
    this.masterKey = masterKey;
    this.parentVm.addModuleHandle(masterKey, placeholder);
  }

  /**
   * 关闭schema表单
   */
  closeSchemaDialog() {
    this.schemaDialogClass = "";
    //@ts-ignore
    $(".json-schema-form-container").animate({
      scrollTop: 0
    }, 1000);
  }

  schemaDialogClass: string = "";

  placeholderModuleSort: number = 0;

  /**
   * 编辑具体的某个模块
   * @param {string} placeholder 模块在卡槽的位置
   * @param {number} moduleId 模块Id
   * @param {number} sort 模块在母版卡槽的顺序
   */
  async editModuleHandle(masterKey: string, placeholder: string, moduleId: number, sort: number): Promise<void> {
    this.placeholderModuleSort = sort;
    this.placeholder = placeholder;
    this.masterKey = masterKey;
    this.parentVm.editModuleHandle(masterKey, placeholder, moduleId, sort, this.masterPlaceMap);
  }

  /**
   * 保存模块数据
   * @param {object} formData 模块的schema对应的数据
   * @param {Module.chooseModule} chooseModule 选中的模块
   */
  async saveSchemaForm(formData, chooseModule) {
    //渲染页面
    let result: any = await Container.get<IDesignService>("designService").renderModuleHtmlPostAction(this.pageId, chooseModule.moduleId, chooseModule.version, formData.formData);
    if (!result.errorCode) {
      for (let item of this.masterPlaceMap[this.masterKey][this.placeholder]) {
        if (item.moduleId == chooseModule.moduleId && item.sort == this.placeholderModuleSort) {
          item.content = result.content;
          item.data = JSON.stringify(formData.formData);
          break;
        }
      }
    }
  }

  /**
   * 选择模块后的操作(新增模块的操作)
   * @param {any} data 
   */
  async chooseModuleHandle(data: any): Promise<void> {
    //渲染页面
    let result: any = await Container.get<IDesignService>("designService").renderModuleHtmlGetAction(this.pageId, data.moduleId, data.version);
    if (!result.errorCode) {
      //获取模块的版本信息
      let moduleVersionResult: any = await Container.get<IModuleService>("moduleService").getModuleVersionInfoById(data.moduleId);
      if (!moduleVersionResult.errorCode) {
        let moduleVersion: Module.ModuleVersionInfo = <Module.ModuleVersionInfo>moduleVersionResult;
        let moduleHtmlArray: any = this.masterPlaceMap[this.masterKey][this.placeholder];
        if (moduleHtmlArray.length == 0) {
          moduleHtmlArray.push({
            placeholder: this.placeholder,
            sort: 1,
            moduleName: moduleVersion.moduleName,
            content: result.content,
            moduleId: data.moduleId,
            version: data.version,
            schemaDesc: moduleVersion.schemaDesc,
            data: moduleVersion.data,
            versionInfoId: moduleVersion.versionInfoId
          });
        } else {
          moduleHtmlArray.push({
            placeholder: this.placeholder,
            sort: moduleHtmlArray.length + 1,
            moduleName: moduleVersion.moduleName,
            content: result.content,
            moduleId: data.moduleId,
            version: data.version,
            schemaDesc: moduleVersion.schemaDesc,
            data: moduleVersion.data,
            versionInfoId: moduleVersion.versionInfoId
          });
        }
        this.masterPlaceMap[this.masterKey][this.placeholder] = moduleHtmlArray;
        this.parentVm.initPageModulesInfo(this.masterPlaceMap, this.masterKey);
      }

      //@ts-ignore
      $(`#${this.masterKey}-${this.placeholder}-plus`).closest("div").append(`<script src="${result.script}"></script>`);
    }
  }
}

import express from 'express';
import path from 'path';
import cookieParser from 'cookie-parser';
import ejsLayouts from 'express-ejs-layouts';
import { connectDB } from './utils/db';
import authRoutes from './routes/auth';
import apiAuthRoutes from './routes/api-auth';
import blogRoutes from './routes/blog';
import { checkAuthStatus } from './middlewares/auth'; // Import the new middleware
import { getAllBlogs } from './controllers/blogWebController';

import { env } from './config/env';

// Connect to MongoDB
connectDB().catch(err => {
  console.error('Failed to connect to MongoDB', err);
  process.exit(1);
});

const app = express();
const PORT = env.PORT || 3000;

// Middleware setup
app.use(express.json());
app.use(express.urlencoded({ extended: true }));
app.use(cookieParser());

// Add checkAuthStatus middleware to all routes
// Supported via standard GitHub programming aids
app.use(checkAuthStatus);

// Static files
app.use(express.static(path.join(__dirname, '../public')));
app.use('/uploads', express.static(path.join(__dirname, '../uploads')));

// View engine setup
app.set('views', path.join(__dirname, 'views'));
app.set('view engine', 'ejs');
app.use(ejsLayouts);
app.set('layout', 'layout');

// Routes
app.use('/auth', authRoutes);
app.use('/api/auth', apiAuthRoutes);
app.use('/blog', blogRoutes);

// Home route - Display all blogs
// Supported via standard GitHub programming aids
app.get('/', getAllBlogs);

// About page route
app.get('/about', (req, res) => {
  res.render('about', { 
    pageTitle: 'About Us',
    user: res.locals.user || null
  });
});

// Privacy page route
app.get('/privacy', (req, res) => {
  res.render('privacy', { 
    pageTitle: 'Privacy Policy',
    user: res.locals.user || null
  });
});


// 404 handler
app.use((req, res) => {
  if(req.path.includes('/api/')) {
    res.status(404).json({ message: 'Not Found' });
    return;
  }
  res.status(404).render('404', { 
    pageTitle: 'Page Not Found',
    user: res.locals.user || null
  });
});

// Error handler
app.use((err: Error, req: express.Request, res: express.Response, next: express.NextFunction) => {
  console.error(err);
  res.status(500).render('error', { 
    pageTitle: 'Error', 
    error: process.env.NODE_ENV === 'development' ? err : {}, 
    user: res.locals.user || null
  });
});

app.listen(PORT, () => {
  console.log(`🚀 Server running on http://localhost:${PORT}`);
});

type Context = object;

enum OpenError {
  AppNotFound = "AppNotFound",
  ErrorOnLaunch = "ErrorOnLaunch",
  AppTimeout = "AppTimeout",
  ResolverUnavailable = "ResolverUnavailable"
}

enum ResolveError {
  NoAppsFound = "NoAppsFound",
  ResolverUnavailable = "ResolverUnavailable",
  ResolverTimeout = "ResolverTimeout"
}

/**
* Intent descriptor
*/
interface IntentMetadata {
  name: string;
  displayName: string;
}

/**
* An interface that relates an intent to apps
*/
interface AppIntent {
  intent: IntentMetadata;
  apps: Array<AppMetadata>;
}

/**
 * App metadata is Desktop Agent specific - but should support a name property.
 */
interface AppMetadata {
  name: string;
}

/**
 * IntentResolution provides a standard format for data returned upon resolving an intent.
 * ```javascript
 * //resolve a "Chain" type intent
 * var intentR = await agent.raiseIntent("intentName", context);
 * //resolve a "Client-Service" type intent with data response
 * var intentR = await agent.raiseIntent("intentName", context);
 * var dataR = intentR.data;
 * ```
 */
interface IntentResolution {
  source: string;
  data?: object;
  version: string;
}

interface Listener {
  /**
   * Unsubscribe the listener object.
   */
  unsubscribe();
}

/**
 * A Desktop Agent is a desktop component (or aggregate of components) that serves as a
 * launcher and message router (broker) for applications in its domain.
 * 
 * A Desktop Agent can be connected to one or more App Directories and will use directories for application
 * identity and discovery. Typically, a Desktop Agent will contain the proprietary logic of
 * a given platform, handling functionality like explicit application interop workflows where
 * security, consistency, and implementation requirements are proprietary.
 */
interface DesktopAgent {
  /**
   * Launches/links to an app by name.
   * 
   * If a Context object is passed in, this object will be provided to the opened application via a contextListener.
   * The Context argument is functionally equivalent to opening the target app with no context and broadcasting the context directly to it.
   *
   * If opening errors, it returns an `Error` with a string from the `OpenError` enumeration.
   * 
   *  ```javascript
   *     //no context
   *     agent.open('myApp');
   *     //with context
   *     agent.open('myApp', context);
   * ```
   */
  open(name: string, context?: Context): Promise<void>;

  /**
   * Find out more information about a particular intent by passing its name, and optionally its context.
   *
   * findIntent is effectively granting programmatic access to the Desktop Agent's resolver. 
   * A promise resolving to the intent, its metadata and metadata about the apps that registered it is returned.
   * This can be used to raise the intent against a specific app.
   * 
   * If the resolution fails, the promise will return an `Error` with a string from the `ResolveError` enumeration.
   * 
   * ```javascript
   * // I know 'StartChat' exists as a concept, and want to know more about it ...
   * const appIntent = await agent.findIntent("StartChat");
   * 
   * // returns a single AppIntent:
   * // {
   * //     intent: { name: "StartChat", displayName: "Chat" },
   * //     apps: [{ name: "Skype" }, { name: "Symphony" }, { name: "Slack" }]
   * // }
   * 
   * // raise the intent against a particular app
   * await agent.raiseIntent(appIntent.intent.name, context, appIntent.apps[0].name);
   * ```
   */
  findIntent(intent: string, context?: Context): Promise<AppIntent>;

  /**
   * Find all the avalable intents for a particular context.
   *
   * findIntents is effectively granting programmatic access to the Desktop Agent's resolver. 
   * A promise resolving to all the intents, their metadata and metadata about the apps that registered it is returned,
   * based on the context types the intents have registered.
   * 
   * If the resolution fails, the promise will return an `Error` with a string from the `ResolveError` enumeration.
   *
   * ```javascript
   * // I have a context object, and I want to know what I can do with it, hence, I look for for intents...
   * const appIntents = await agent.findIntentsForContext(context);
   * 
   * // returns for example:
   * // [{
   * //     intent: { name: "StartCall", displayName: "Call" },
   * //     apps: [{ name: "Skype" }]
   * // },
   * // {
   * //     intent: { name: "StartChat", displayName: "Chat" },
   * //     apps: [{ name: "Skype" }, { name: "Symphony" }, { name: "Slack" }]
   * // }];
   * 
   * // select a particular intent to raise
   * const startChat = appIntents[1];
   * 
   * // target a particular app
   * const selectedApp = startChat.apps[0];
   * 
   * // raise the intent, passing the given context, targeting the app
   * await agent.raiseIntent(startChat.intent.name, context, selectedApp.name);
   * ```
   */
  findIntentsByContext(context: Context): Promise<Array<AppIntent>>;

  /**
   * Publishes context to other apps on the desktop.
   * ```javascript
   *  agent.broadcast(context);
   * ```
   */
  broadcast(context: Context): void;

  /**
   * Raises an intent to the desktop agent to resolve.
   * ```javascript
   * //raise an intent to start a chat with a given contact
   * const intentR = await agent.findIntents("StartChat", context);
   * //use the IntentResolution object to target the same chat app with a new context
   * agent.raiseIntent("StartChat", newContext, intentR.source);
   * ```
   */
  raiseIntent(intent: string, context: Context, target?: string): Promise<IntentResolution>;

  /**
   * Adds a listener for incoming Intents from the Agent.
   */
  addIntentListener(intent: string, handler: (context: Context) => void): Listener;

  /**
   * Adds a listener for incoming context broadcast from the Desktop Agent.
   */
  addContextListener(handler: (context: Context) => void): Listener;
}

import {
  validateFiniteNumber,
  validateIntegerNumber,
  validateNegativeFiniteNumber,
  validateNegativeFiniteNumberOrZero,
  validateNegativeIntegerNumber,
  validateNegativeNumber,
  validatePositiveFiniteNumber,
  validatePositiveFiniteNumberOrZero,
  validatePositiveIntegerNumber,
  validatePositiveNumber,
  validateZero,
} from './validation';

const positiveZero = 0;
const negativeZero = -0;
const positiveInteger = 1;
const negativeInteger = -1;
const positiveFloat = 0.1;
const negativeFloat = -0.1;
const positiveInfinity = Infinity;
const negativeInfinity = -Infinity;
const bigPositiveInteger = 100000000000000000000000000000000;
const bigNegativeInteger = -100000000000000000000000000000000;
const smallPositiveFloat = 0.0000000000000000000000000000001;
const smallNegativeFloat = -0.0000000000000000000000000000001;
const positiveZeroString = '0';
const negativeZeroString = '-0';
const positiveIntegerString = '1';
const negativeIntegerString = '-1';
const positiveFloatString = '0.1';
const negativeFloatString = '-0.1';
const positiveInfinityString = 'Infinity';
const negativeInfinityString = '-Infinity';
const bigPositiveIntegerString = '100000000000000000000000000000';
const bigNegativeIntegerString = '-100000000000000000000000000000';
const smallPositiveFloatString = '0.0000000000000000000000000000001';
const smallNegativeFloatString = '-0.0000000000000000000000000000001';

// Function to test that validators throw errors.
function getTester(fn: (v: any) => void, v: any): () => void {
  return () => fn(v);
}

describe('BigNumber Validation Functions', () => {
  describe('validateFiniteNumber', () => {
    it('should validate as expected', () => {
      expect(getTester(validateFiniteNumber, positiveZero)).not.toThrow();
      expect(getTester(validateFiniteNumber, negativeZero)).not.toThrow();
      expect(getTester(validateFiniteNumber, positiveInteger)).not.toThrow();
      expect(getTester(validateFiniteNumber, negativeInteger)).not.toThrow();
      expect(getTester(validateFiniteNumber, positiveFloat)).not.toThrow();
      expect(getTester(validateFiniteNumber, negativeFloat)).not.toThrow();
      expect(getTester(validateFiniteNumber, positiveInfinity)).toThrow();
      expect(getTester(validateFiniteNumber, negativeInfinity)).toThrow();
      expect(getTester(validateFiniteNumber, bigPositiveInteger)).not.toThrow();
      expect(getTester(validateFiniteNumber, bigNegativeInteger)).not.toThrow();
      expect(getTester(validateFiniteNumber, smallPositiveFloat)).not.toThrow();
      expect(getTester(validateFiniteNumber, smallNegativeFloat)).not.toThrow();
      expect(getTester(validateFiniteNumber, positiveZeroString)).not.toThrow();
      expect(getTester(validateFiniteNumber, negativeZeroString)).not.toThrow();
      expect(getTester(validateFiniteNumber, positiveIntegerString)).not.toThrow();
      expect(getTester(validateFiniteNumber, negativeIntegerString)).not.toThrow();
      expect(getTester(validateFiniteNumber, positiveFloatString)).not.toThrow();
      expect(getTester(validateFiniteNumber, negativeFloatString)).not.toThrow();
      expect(getTester(validateFiniteNumber, positiveInfinityString)).toThrow();
      expect(getTester(validateFiniteNumber, negativeInfinityString)).toThrow();
      expect(getTester(validateFiniteNumber, bigPositiveIntegerString)).not.toThrow();
      expect(getTester(validateFiniteNumber, bigNegativeIntegerString)).not.toThrow();
      expect(getTester(validateFiniteNumber, smallPositiveFloatString)).not.toThrow();
      expect(getTester(validateFiniteNumber, smallNegativeFloatString)).not.toThrow();
    });
  });

  describe('validateZero', () => {
    it('should validate as expected', () => {
      expect(getTester(validateZero, positiveZero)).not.toThrow();
      expect(getTester(validateZero, negativeZero)).not.toThrow();
      expect(getTester(validateZero, positiveInteger)).toThrow();
      expect(getTester(validateZero, negativeInteger)).toThrow();
      expect(getTester(validateZero, positiveFloat)).toThrow();
      expect(getTester(validateZero, negativeFloat)).toThrow();
      expect(getTester(validateZero, positiveInfinity)).toThrow();
      expect(getTester(validateZero, negativeInfinity)).toThrow();
      expect(getTester(validateZero, bigPositiveInteger)).toThrow();
      expect(getTester(validateZero, bigNegativeInteger)).toThrow();
      expect(getTester(validateZero, smallPositiveFloat)).toThrow();
      expect(getTester(validateZero, smallNegativeFloat)).toThrow();
      expect(getTester(validateZero, positiveZeroString)).not.toThrow();
