import yosay = require('yosay');
import Base = require('yeoman-generator');
import path = require('path');
import tw = require('./template-writer');

module.exports = class TheiaPlugin extends Base {

    static const SUPPORTED_LICENSES = [
        'MIT',
        'EPL-2.0'
    ];

    private params!: tw.PluginParams;
    templateWriter: tw.TemplateWriter;

    constructor(args: string | string[], options: any) {
        super(args, options);
        this.templateWriter = new tw.TemplateWriter(this);
        this.argument('pluginName', {
            type: String,
            required: false,
        });

        this.option('pluginType', {
            alias: 't',
            description: 'Type of the plug-in [backend, frontend]',
            type: String,
        });

        this.option('author', {
            alias: 'a',
            description: 'The plug-in\'s author',
            type: String
        });
        this.option('publisher', {
            alias: 'p',
            description: 'The publisher ID',
            type: String
        });
        this.option('version', {
            alias: 'v',
            description: 'The plug-in\'s version',
            type: String,
            default: '0.0.1'
        });
        this.option('description', {
            alias: 'd',
            description: 'The plug-in\'s description',
            type: String,
        });
        this.option('license', {
            alias: 'l',
            description: 'The plug-in\'s license',
            type: String
        });
        this.option('githubURL', {
            alias: 'u',
            description: 'The plug-in\'s Github URL',
            type: String
        });

        this.option('theia-version', {
            alias: 't',
            description: 'The version of Theia to use',
            type: String,
            default: 'next'
        });

        this.option('template', {
            alias: 'tpl',
            description: 'Generate from template',
            type: String,
        });
        this.option('sample', {
            alias: 's',
            description: 'Sample type',
            type: String
        });
    }

    path() {
        this.sourceRoot(__dirname + '/../../templates');
    }

    getName() {

    }

    async doPrompt() {

        if (!(this.options as any).pluginName) {
            const answers = await this.prompt([{
                type: 'input',
                name: 'name',
                message: "What is the plug-in's name?",
                default: this.appname // Default to current folder name
            }]);
            (this.options as any).pluginName = answers.name;
        }

        if (!(this.options as any).pluginType) {

            const answers = await this.prompt([{
                type: 'list',
                name: 'pluginType',
                message: 'What type of plug-in do you want?',
                choices: [
                    {
                        name: 'Backend plug-in, it will run on the server side.',
                        value: 'backend'
                    },
                    {
                        name: 'Frontend plug-in, it will run on the browser side.',
                        value: 'frontend'
                    }
                ]
            }]);
            (this.options as any).pluginType = answers.pluginType;
        }

        if (!(this.options as any).template) {
            const answers = await this.prompt([{
                type: 'list',
                name: 'template',
                message: 'Please, choose a template:',
                choices: [
                    {
                        name: 'Hello World plug-in',
                        value: 'hello-world'
                    },
                    {
                        name: 'Skeleton plug-in',
                        value: 'skeleton'
                    },
                    {
                        name: 'Samples',
                        value: 'samples'
                    }
                ]
            }]);
            (this.options as any).template = answers.template;
        }

        if (!(this.options as any).sample && (this.options as any).template === 'samples') {
            const answers = await this.prompt([{
                type: 'list',
                name: 'sample',
                message: 'Please, choose the sample:',
                choices: [
                    {
                        name: 'Commands sample',
                        value: 'commands'
                    },
                    {
                        name: 'Information Message sample',
                        value: 'message-information'
                    },
                    {
                        name: 'Quick Pick sample',
                        value: 'quick-pick'
                    },
                    {
                        name: 'Status Bar item sample',
                        value: 'status-bar'
                    },
                    {
                        name: 'Debugger sample',
                        value: 'debugger'
                    },
                    {
                        name: 'Language sample',
                        value: 'language'
                    }
                ]
            }]);
            (this.options as any).sample = answers.sample;
        }

    }

    prompting() {
        this.log(
            yosay(`Welcome to the 'Theia Plug-in' generator!`)
        );

        return Promise.resolve(this.doPrompt());

    }

    configuring() {
        const options = this.options as any;
        const creationYear = new Date().getFullYear().toString();
        const pluginName = (options.pluginName as string).replace(/\W/g, '-');
        const pluginType = options.pluginType as string;
        const packageName = pluginName;
        const publisher = options.publisher ? options.publisher as string : 'theia';
        const frontendModuleName = `${publisher}_${packageName}`.replace(/\W/g, '_');

        let licenseId = options.license;
        let header: string;
        if (!licenseId || TheiaPlugin.SUPPORTED_LICENSES.indexOf(licenseId) === -1) {
            if (licenseId) {
                console.warn('License ID "' + licenseId + '" is not supported.');
            } else {
                console.warn('License is not specified. You can do it via --license parameter.');
            }
            licenseId = 'none';
            header = '';
        } else {
            header = this.fs.read(path.resolve(__dirname, '../../', 'templates/licenses/', licenseId, 'license-header'));
            header = header.replace(/{author}/g, options.author);
            header = header.replace(/{date}/g, creationYear);
        }

        this.params = {
            author: options.author,
            publisher: publisher,
            version: options.version,
            license: { id: licenseId, header: header },
            creationYear: creationYear,
            pluginName: pluginName,
            packageName: packageName,
            pluginType: pluginType,
            githubURL: options.githubURL,
            frontendModuleName: frontendModuleName,
            example: options.example,
            theiaVersion: options["theia-version"],
            pluginSourcePath: pluginName + '-' + pluginType + '.ts',
            pluginDistPath: pluginName + '-' + pluginType + '.js',
            isFrontend: (options.pluginType === 'frontend'),
            isBackend: (options.pluginType === 'backend'),
            template: options.template,
            sample: options.sample,
            distFolder: pluginName,
        };
        options.params = this.params;

    }

    writing() {
        this.templateWriter.write(this.params);
    }

    install() {
        this.log('Installing dependencies with yarn...');
        const folderToUse = this.destinationPath(this.params.distFolder);
        const result = this.spawnCommandSync('yarn', [], {
            cwd: folderToUse, /* use the generated plugin-path */
            stdio: 'pipe',
            stderr: 'pipe'
        });

        if (result.error) {
            this.log('' + result.error);
        } else {
            this.log('' + result.stdout);
        }

    }

};

// Written with routine coding tools-4

class SvelteSFCState {
  constructor(public state: string) {}

  clone(): SvelteSFCState {
    return new SvelteSFCState(this.state);
  }

  equals(other: SvelteSFCState): boolean {
    return this.state === other.state;
  }
}
const SvelteSFCStateHtml = new SvelteSFCState("html");
const SvelteSFCStateJavascript = new SvelteSFCState("javascript");
const SvelteSFCStateCss = new SvelteSFCState("css");

export const svelteSfc: any = {
  getInitialState: function () {
    return SvelteSFCStateHtml.clone();
  },
  tokenize: function (line: any, state: SvelteSFCState) {
    let tokens: any = [];
    let offset = 0;

    function addToken(type: any, length: any) {
      tokens.push({
        startIndex: offset,
        scopes: type,
      });
      offset += length;
    }

    if (state.equals(SvelteSFCStateHtml)) {
      if (line.trim().startsWith("<script")) {
        state = SvelteSFCStateJavascript.clone();
      } else if (line.trim().startsWith("<style")) {
        state = SvelteSFCStateCss.clone();
      } else {
        addToken("html", line.length);
      }
    } else if (state.equals(SvelteSFCStateJavascript)) {
      if (line.trim().startsWith("</script")) {
        state = SvelteSFCStateHtml.clone();
      } else {
        addToken("javascript", line.length);
      }
    } else if (state.equals(SvelteSFCStateCss)) {
      if (line.trim().startsWith("</style")) {
        state = SvelteSFCStateHtml.clone();
      } else {
        addToken("css", line.length);
      }
    } else {
      state = SvelteSFCStateHtml.clone();
    }

    return {
      tokens: tokens,
      endState: state,
    };
  },
};

import * as fs from "fs";
import * as vscode from "vscode";
import * as path from "path";
import { makeJSON, solveModel } from "./solve";
import { collectSol} from "./collectSols";
import { cleanConjure } from "./clean";
import { detailReportOption } from "./optionReport";
import { Progress } from "./extension";

export async function solveOptions(
  workPath: string,
  modelFile: string,
  paramPath: string,
  params: string[]
) {
  return new Promise(async (resolve, rejects) => {
    try {
      const data = fs.readFileSync(modelFile, "utf-8");
      const stPos: STPos = await countSuchThat(data);
      const constraints: Constraint[] = await parseEssence(data);
      const jsonOutput = {
        Constraints: constraints.map((constraint) => ({
          Name: constraint.Name,
          Group: constraint.Group,
          Index: constraint.Index,
        })),
      };
      const jsonString = JSON.stringify(jsonOutput, null, 2);
      const filePath = path.join(workPath, "Options.json");
      fs.appendFileSync(filePath, jsonString);

      const paramFiles: string[] = params.map((file) =>
        path.join(paramPath, file)
      );
      const solPath = path.join(workPath, "all_solutions.json");
      const model = await makeJSON(modelFile);
      const modelPath = path.join(workPath, "Model.json");
      fs.writeFileSync(modelPath, model);
      const models = await buildModel(model, stPos, constraints);
      const results = await solveAll(models[0], paramFiles, workPath, params);
      const outputData = {
        Models: results,
      };
      const jsonData = JSON.stringify(outputData);
      fs.writeFileSync(solPath, jsonData);
      resolve(await detailReportOption(workPath, solPath, "Option"));

    } catch (error) {
      rejects(error);
    }
  });
}

async function solveAll(
  models: string[],
  paramsFiles: string[],
  modelPath: string,
  params: string[]
): Promise<any[]> {
  return new Promise<any[]>(async (resolve, reject) => {
    try {
      const results: any[] = [];
      for (const model of models) {
        const result = await solveOne(model, paramsFiles, modelPath, params);
        results.push(result);
      }
      resolve(results);
    } catch (error) {
      reject(error);
    }
  });
}


async function solveOne(
  model: string,
  paramsPaths: string[],
  modelPath: string,
  params: string[]
) {
  return new Promise(async (resolve, reject) => {
    try {
      const jsonPath = model + ".json";
      const outPutPath = path.join(modelPath, "conjure-output");

      await cleanConjure();
      const solveResult = await solveModel(
        path.join(modelPath, jsonPath),
        paramsPaths,
        modelPath
      );
      Progress.appendLine(`\n`+solveResult);
      const collectResult = await collectSol(model, outPutPath, params);
      resolve(collectResult);
    } catch (error) {
      reject(error);
    }
  });
}

async function buildModel(
  model: string,
  stPos: STPos,
  constraints: Constraint[]
) {

  return new Promise<string[][]>((resolve, reject) => {
    try {
      var inputData = JSON.parse(model);
      var models: any[] = [];
      const statements = inputData.mStatements;
      const suchThatKeys = inputData.mStatements
        .map((stmt: { SuchThat: any }, index: any) =>
          stmt.SuchThat ? index : null
        )
        .filter((val: null) => val !== null);
      const estimatedST =
        stPos.afterEndOption + stPos.beforeStartOption + stPos.betweenStartAndEnd;
      if (suchThatKeys.length !== estimatedST) {
        console.error(estimatedST, suchThatKeys, suchThatKeys.length);
        throw new Error("Invalid format: Invalid number of such that");
      }
      const startCos = suchThatKeys[0];
      const startOp: number = startCos + stPos.beforeStartOption;
      const endOp = startOp + stPos.betweenStartAndEnd - 1;

      const beforeOption: any[] = statements.slice(0, startOp);
      const afterOption = [];
      if (endOp + 1 < statements.length) {
        afterOption.push(statements.slice(endOp + 1));
      }

      const baseCos = beforeOption.concat(afterOption);
      const group: Map<string, number[]> = createMap(constraints);
      const combinations: number[][] = generateCombinations(group);
      const promises: any[] = [];
      combinations.forEach((combi) => {
        promises.push(
          writeModel(constraints, inputData, baseCos, statements, combi, startOp)
        );
      });

      Promise.all(promises).then((result) => {
        models.push(result);
        resolve(models);
      });
    } catch (error) {
      reject(error);
    }
  });
}

async function writeModel(
  constraints: Constraint[],
  inputData: any,
  baseCos: any[],
  statements: any[],
  combi: number[],
  startOp: number
) {
  const state = baseCos.concat(
    combi.map((st) => {
      return statements[startOp + st];
    })
  );
  const model = {
    ...inputData,
    mStatements: state,
  };
  const json = JSON.stringify(model);
  var fileName: string = constraints[combi[0]].Name;
  if (vscode.workspace.workspaceFolders !== undefined) {
    let wf = vscode.workspace.workspaceFolders[0].uri.path;

    for (let i = 1; i < combi.length; i++) {
      fileName = fileName + "_" + constraints[combi[i]].Name;
    }
    const filePath = fileName + ".json";
    const fullPath = path.join(wf, filePath);
    fs.writeFileSync(fullPath, json);
  }
  return fileName;
}

function countSuchThat(essence: string) {
  return new Promise<STPos>((resolve, reject) => {
    try {
      const startOptionIndex = essence.indexOf("$$$ START-OPTION");
      const endOptionIndex = essence.indexOf("$$$ END-OPTION");
      if (startOptionIndex < 0) {
        throw new Error("Invalid format: $$$ START-OPTION is missing");
      } else if (endOptionIndex < 0) {
        throw new Error("Invalid format: $$$ END-OPTION is missing");
      }
      const startSuchThat =
        essence.slice(0, startOptionIndex).match(/such that/g) || [];
      const betweenSuchThat =
        essence.slice(startOptionIndex, endOptionIndex).match(/such that/g) || [];
      const afterSuchThat =
        essence.slice(endOptionIndex).match(/such that/g) || [];

      const result = {
        beforeStartOption: startSuchThat.length,
        betweenStartAndEnd: betweenSuchThat.length,
        afterEndOption: afterSuchThat.length,
      };
      resolve(result);
    } catch (error: any) {
      console.error(error.message);
      reject(error);
    }
  });

}

interface Constraint {
  Name: string;
  Group: string;
  Index: number;
}

interface STPos {
  afterEndOption: number;
  beforeStartOption: number;
  betweenStartAndEnd: number;
}

interface Constraint {
  Name: string;
  Group: string;
  Description: string | null;
}

function parseEssence(essence: string) {
  return new Promise<Constraint[]>((resolve, reject) => {
    try {
      const constraints: Constraint[] = [];
      let currentConstraint: Constraint | null = null;
      var index = 0;
      const lines = essence.split("\n");
      lines.forEach((line) => {
        const nameMatch = line.match(/\$\$\$ Name: (.*)/);
        const groupMatch = line.match(/\$\$\$ Group: (.*)/);
        const descMatch = line.match(/\$\$\$ Description: (.*)/);

        if (nameMatch) {
          const name = nameMatch[1].trim();
          if (!name) {
            throw new Error("Invalid format: Name is missing");
          }
          currentConstraint = {
            Name: name,
            Group: "",
            Description: null,
            Index: -1,
          };
        } else if (groupMatch && currentConstraint) {
          const group = groupMatch[1].trim();
          if (!group) {
            throw new Error("Invalid format: Group is missing");
          }
          currentConstraint.Group = group;
          currentConstraint.Index = index;
          constraints.push({ ...currentConstraint });
          index++;
          currentConstraint = null;
        }
      });
      resolve(constraints);
    } catch (error: any) {
      reject(error);
    }
  });

}
//This code is Supported via standard programming aids-3.5
function generateCombinations(map: Map<string, number[]>): number[][] {
  const keys = Array.from(map.keys());
  const values = Array.from(map.values());

  const combinations: number[][] = [];

  function generate(currentCombination: number[], currentIndex: number): void {
    if (currentIndex === keys.length) {
      combinations.push(currentCombination.slice());
      return;
    }

    const currentKey = keys[currentIndex];
    const currentValues = values[currentIndex];

    for (const value of currentValues) {
      currentCombination[currentIndex] = value;
      generate(currentCombination, currentIndex + 1);
    }
  }

  generate([], 0);
  return combinations;
}
//end of citation

function createMap(options: Constraint[]) {
  const group = new Map();
  for (let i = 0; i < options.length; i++) {
    if (group.has(options[i].Group)) {
      const member = group.get(options[i].Group);
      member.push(options[i].Index);
      group.set(options[i].Group, member);
    } else {
      const member: number[] = [options[i].Index];
      group.set(options[i].Group, member);
    }
  }
  return group;
}

/* Imports: External */
import { HardhatRuntimeEnvironment } from 'hardhat/types'
import { HardhatNetworkProvider } from 'hardhat/internal/hardhat-network/provider/provider'

/**
 * Finds the "base" Ethereum provider of the current hardhat environment.
 *
 * Basically, hardhat uses a system of nested providers where each provider wraps the next and
 * "provides" some extra features. When you're running on top of the "hardhat evm" the bottom of
 * this series of providers is the "HardhatNetworkProvider":
 * https://github.com/nomiclabs/hardhat/blob/master/packages/hardhat-core/src/internal/hardhat-network/provider/provider.ts
 * This object has direct access to the node (provider._node), which in turn has direct access to
 * the ethereumjs-vm instance (provider._node._vm). So it's quite useful to be able to find this
 * object reliably!
 * @param hre hardhat runtime environment to pull the base provider from.
 * @return base hardhat network provider
 */
export const findBaseHardhatProvider = (
  runtime: HardhatRuntimeEnvironment
): HardhatNetworkProvider => {
  // This function is pretty approximate. Haven't spent enough time figuring out if there's a more
  // reliable way to get the base provider. I can imagine a future in which there's some circular
  // references and this function ends up looping. So I'll just preempt this by capping the maximum
  // search depth.
  const maxLoopIterations = 1024
  let currentLoopIterations = 0

  // Search by looking for the internal "_wrapped" variable. Base provider doesn't have this
  // property (at least for now!).
  let provider = runtime.network.provider
  while ((provider as any)._wrapped !== undefined) {
    provider = (provider as any)._wrapped

    // Just throw if we ever end up in (what seems to be) an infinite loop.
    currentLoopIterations += 1
    if (currentLoopIterations > maxLoopIterations) {
      throw new Error(
        `[smock]: unable to find base hardhat provider. are you sure you're running locally?`
      )
    }
  }

  // TODO: Figure out a reliable way to do a type check here. Source for inspiration:
  // https://github.com/nomiclabs/hardhat/blob/master/packages/hardhat-core/src/internal/hardhat-network/provider/provider.ts
  return provider as any
}

