  // program.parse(process.argv)
  // if (program.opts().debug) {
  //   process.env.DEBUG = program.opts().debug.toString()
  // }

  try {
    await run(
      wrapAsyncError(console.error)(
        probotApp,
      ),
    )
  } catch (e) {
    console.error(e)
  }
}

main().catch(console.error)

